const AREAS={"ruae":{"name":"Reading for Understanding, Analysis & Evaluation","short":"RUAE"},"ce":{"name":"Critical Essay","short":"Critical essay"},"skills":{"name":"Scottish Text — How the Section Works","short":"Scottish text skills"},"drama":{"name":"Scottish Set Texts — Drama","short":"Drama set texts"},"prose":{"name":"Scottish Set Texts — Prose","short":"Prose set texts"},"poetry":{"name":"Scottish Set Texts — Poetry","short":"Poetry set texts"},"pf":{"name":"Portfolio–Writing & Spoken Language","short":"Portfolio"},"term":{"name":"Terminology & Techniques","short":"Terminology"}};
const TOPICS={
"ruae_paper":{"name":"The RUAE Paper & Own-Words Questions","area":"ruae","questions":[{"q":"How many marks is the Higher English Reading for Understanding, Analysis and Evaluation (RUAE) paper worth?","o":["30","20","40","25"],"l":1,"e":"RUAE is worth 30 marks — 30% of the overall course award."},{"q":"How long do you have for the Higher RUAE paper?","o":["1 hour 30 minutes","1 hour","1 hour 45 minutes","2 hours"],"l":1,"e":"The course specification gives 1 hour 30 minutes for RUAE."},{"q":"What kind of texts are used in the RUAE paper?","o":["Two unseen non-fiction passages linked by theme","One prose fiction extract and one poem","Two previously studied Scottish texts","One unseen newspaper article only"],"l":1,"e":"Candidates read two unseen non-fiction texts connected by theme (often journalism)."},{"q":"Most of the RUAE questions are asked about which passage?","o":["Passage 1","Passage 2","Both equally","Whichever you choose"],"l":2,"e":"A series of questions is based on Passage 1; only the final question deals with both passages."},{"q":"In 2027, on what date is the Higher English exam (RUAE and Critical Reading)?","o":["Friday 7 May 2027","Monday 26 April 2027","Thursday 13 May 2027","Wednesday 19 May 2027"],"l":1,"e":"The 2027 Qualifications Scotland timetable puts both Higher English papers on the morning of Friday 7 May."},{"q":"A question says \"Use your own words in your answer.\" What happens if you copy phrases straight from the passage?","o":["Straight lifts get no marks","You get half marks","You lose a mark from your total","It is fine if you use quotation marks"],"l":2,"e":"Marking instructions state: no marks for straight lifts. You must recast the idea in your own words."},{"q":"What is the best way to tackle an \"own words\" question?","o":["Find the key words, then translate each into your own words so the meaning is kept","Quote the line and explain the technique","Summarise the whole paragraph","Give your own opinion on the topic"],"l":2,"e":"Own-words questions test understanding: identify the relevant ideas, then gloss them in your own language."},{"q":"A 3-mark own-words question asks you to \"explain fully\". How many distinct points should you usually make?","o":["Three","One very long one","Two","Five, to be safe"],"l":2,"e":"Usually 1 mark per clear point; some \"explain fully\" answers allow 2 for a detailed point, but three separate accurate glosses is the safest plan."},{"q":"In an own-words answer, \"gloss\" means…","o":["restating the meaning of a word or phrase in different words","adding a quotation","describing the tone","linking two paragraphs"],"l":1,"e":"To gloss is to explain the meaning in your own words."},{"q":"Which answer best glosses: \"The council's plan was greeted with derision\"?","o":["People mocked/scorned the plan","People were confused by the plan","People ignored the plan","People welcomed the plan warmly"],"l":2,"e":"\"Derision\" means contemptuous ridicule — mocking scorn."},{"q":"Which answer best glosses: \"Her optimism proved short-lived\"?","o":["Her hopefulness did not last long","She was always negative","She was only briefly sad","She lived a short life"],"l":2,"e":"Optimism = hopefulness; short-lived = lasting only a short time."},{"q":"Which best glosses: \"The new law is a blunt instrument\"?","o":["It is crude and does not target the problem precisely","It is extremely sharp and effective","It is violent","It was passed quickly"],"l":2,"e":"\"Blunt instrument\" is a metaphor for a method that is unsubtle and imprecise."},{"q":"A question asks: \"Identify two reasons the writer gives… Use your own words.\" The passage gives four. What should you do?","o":["Give two clearly, in your own words — extra correct points do no harm but wrong ones waste time","Give all four to be safe, copied exactly","Give one detailed reason","Give your own reasons"],"l":3,"e":"Answer what is asked. Only the required number of accurate, glossed points earn marks."},{"q":"Which command word in RUAE usually signals an understanding (own words) question?","o":["Identify / explain … use your own words","Analyse how","Evaluate","Discuss how"],"l":1,"e":"The specification lists \"identify/explain\" (with \"use your own words\") for understanding and inference questions."},{"q":"What does \"inference\" mean in RUAE?","o":["Working out what is implied but not stated directly","Copying the writer's exact words","Naming a technique","Counting the words in a sentence"],"l":2,"e":"Inferring meaning is a skill listed in the course specification — reading between the lines."},{"q":"A question asks you to explain \"in what way\" protesters are different from what we expect. For full marks you need to…","o":["show understanding of BOTH what we expect and what they are actually like","describe the protesters only","quote the paragraph","give your opinion of protest"],"l":3,"e":"The specimen paper's marking for this type of question requires both sides of the contrast."},{"q":"Read this sentence from a passage about city life:\n\n\"Town planners once dreamed of gleaming motorways slicing through the city; today they talk of pocket parks, cycle lanes and streets where children can play.\"\n\nExplain the change in town planners' thinking. Use your own words in your answer.","m":2,"p":["In the past planners wanted big, modern roads for cars running right through the city","Now they want small green spaces / more room for cyclists","Now they want safer streets that are designed for people / children rather than traffic"],"l":2,"h":"Say what they wanted before AND what they want now."},{"q":"Read this paragraph:\n\n\"Supporters of the four-day week argue that rested staff make fewer mistakes. They point out that companies which have trialled it report lower sickness rates, and that the promise of a long weekend makes it far easier to attract and keep talented workers.\"\n\nExplain three benefits of the four-day week, according to supporters. Use your own words.","m":3,"p":["Workers who are less tired are more accurate / less error-prone","Fewer staff are off ill","Easier to recruit good employees","Easier to hold on to / retain skilled staff"],"l":2,"h":"Three separate benefits — no straight lifts."},{"q":"Read this paragraph:\n\n\"For years the island's population dwindled as young people left for the mainland. Now remote working has reversed the trend: incomers with laptops have reopened the shop, swelled the school roll and brought the ferry back to a daily timetable.\"\n\nExplain fully how remote working has changed the island. Use your own words.","m":3,"p":["The population had been shrinking / young people moved away, but this has now turned round","The local shop is trading again","More pupils are attending the school","The ferry service has increased to every day"],"l":3,"h":"Before and after — and the specific changes."}]},
"ruae_wordchoice":{"name":"Word Choice","area":"ruae","questions":[{"q":"In RUAE, what is \"word choice\" analysis about?","o":["The connotations of particular words and the effect they create","The number of syllables in each word","Spelling and grammar","The order of paragraphs"],"l":1,"e":"Analyse what a carefully chosen word suggests (its connotations) and how that conveys the writer's ideas or attitude."},{"q":"What are connotations?","o":["The ideas and feelings a word suggests beyond its literal meaning","The dictionary definition of a word","Words that sound alike","The origin of a word"],"l":1,"e":"Denotation is the literal meaning; connotation is what the word suggests or implies."},{"q":"How is a full 2-mark word choice answer usually built?","o":["Quote the word, give its connotations, and link them to the writer's point or attitude","Quote a whole paragraph","Name the technique and stop","Explain the word's dictionary meaning only"],"l":2,"e":"Marking instructions: 2 marks for detailed/insightful comment plus quotation; 1 for basic comment; 0 for quotation alone."},{"q":"How many marks does a quotation on its own (with no comment) earn in an analysis question?","o":["0","1","2","Half a mark"],"l":2,"e":"Marking instructions say \"0 marks for quotation/reference alone\"."},{"q":"\"Commuters were herded onto the platform.\" What does \"herded\" suggest?","o":["They were treated like animals / packed in with no control","They moved quickly and happily","They were well organised","They were walking alone"],"l":2,"e":"\"Herded\" connotes livestock driven en masse — dehumanising and crowded."},{"q":"\"The minister's speech was a masterpiece of evasion.\" The word \"masterpiece\" conveys…","o":["sarcastic admiration for how skilfully he avoided answering","sincere praise for his honesty","that the speech was very long","that he painted while speaking"],"l":2,"e":"\"Masterpiece\" normally praises supreme skill; here it is ironic — he was skilled at dodging."},{"q":"\"Bonus culture has infected every corner of the City.\" What does \"infected\" suggest about the writer's attitude?","o":["Bonus culture is a harmful disease that spreads","Bonus culture is healthy","Bonus culture is limited to one bank","The writer admires bonuses"],"l":2,"e":"Disease imagery/word choice conveys disapproval and the idea of uncontrolled spread."},{"q":"\"Supporters of the scheme insist it will pay for itself.\" Why might the writer choose \"insist\" rather than \"say\"?","o":["It suggests stubborn repetition in the face of doubt, hinting the writer is sceptical","It shows the writer agrees","It is more formal","It suggests the supporters are quiet"],"l":3,"e":"\"Insist\" implies forceful assertion against disagreement — subtly undermining the claim."},{"q":"Which word best conveys a writer's contempt for a new building?","o":["carbuncle","structure","landmark","development"],"l":2,"e":"\"Carbuncle\" (a boil) is strongly derogatory; the others are neutral or positive."},{"q":"Which of these words has the most positive connotations?","o":["thrifty","stingy","miserly","tight-fisted"],"l":2,"e":"All mean careful with money, but \"thrifty\" suggests sensible economy; the others suggest meanness."},{"q":"A writer calls a festival \"a cacophony of drums, dodgems and drunken singing.\" Analysing \"cacophony\" you would say it…","o":["suggests harsh, discordant noise, conveying the writer's irritation","suggests a beautiful harmony","means a large crowd","is a list"],"l":3,"e":"\"Cacophony\" means a harsh mixture of sounds — negative connotations reveal attitude."},{"q":"What is \"register\"?","o":["The level of formality of language","The speed of reading","The structure of a paragraph","A type of punctuation"],"l":2,"e":"Formal, informal, colloquial and slang are registers; shifts in register can create humour or emphasis."},{"q":"\"So the great and the good gathered, nibbling canapés, to save the planet.\" The effect of \"nibbling canapés\" is…","o":["to mock the delegates as comfortable elites whose actions don't match their grand aims","to praise their hospitality","to describe the menu neutrally","to show they were hungry"],"l":3,"e":"The trivial, luxurious detail undercuts the grand purpose — a sarcastic contrast."},{"q":"A word that sounds like what it describes (e.g. \"clatter\") is an example of…","o":["onomatopoeia","alliteration","assonance","oxymoron"],"l":2,"e":"Onomatopoeia imitates sound and can make description vivid."},{"q":"Which phrase would improve a basic word choice answer?","o":["\"…suggests…, which conveys the writer's…\"","\"…is a good word…\"","\"…makes it more interesting…\"","\"…makes you want to read on…\""],"l":1,"e":"Generic comments (\"interesting\", \"makes you read on\") earn nothing; link the connotation to meaning/attitude."},{"q":"Read this sentence:\n\n\"Every summer, tourists swarm over the old town, devouring ice creams and photographing anything that stands still.\"\n\nAnalyse how the writer's word choice conveys a negative attitude to the tourists.","m":2,"p":["'swarm' suggests a mass of insects — overwhelming, invasive, unwelcome numbers","'devouring' suggests greedy, animal-like eating — the tourists are gluttonous / consuming the place","'anything that stands still' suggests thoughtless, indiscriminate behaviour — mocking their lack of real interest"],"l":1,"h":"Pick one word and explore its connotations fully, or two words briefly."},{"q":"Read this paragraph:\n\n\"The new shopping centre squats at the edge of town like a toad. Its car park sprawls across what were once water meadows, and every weekend a sluggish procession of traffic crawls towards it, belching fumes over the villages it has bled dry.\"\n\nBy referring to at least two examples, analyse how the writer's word choice conveys disapproval of the shopping centre.","m":4,"p":["'squats' suggests something ugly, low and lazy that has taken up position without right","'sprawls' suggests untidy, uncontrolled spreading over valuable land","'sluggish'/'crawls' suggest slow, frustrating congestion caused by the centre","'belching' suggests something crude and disgusting / pollution","'bled dry' suggests the centre has drained the life (trade/money) out of the villages like a parasite"],"l":2,"h":"Up to 2 marks per example: quote + detailed comment."},{"q":"Read this sentence:\n\n\"The chairman praised the 'streamlined' workforce — a word that does a lot of heavy lifting when 400 people have just been sacked.\"\n\nAnalyse how the writer's language conveys a critical attitude to the chairman.","m":2,"p":["inverted commas around 'streamlined' show the writer is distancing herself from / mocking the euphemism","'streamlined' makes job losses sound efficient and positive — the writer exposes it as a cover for sackings","'does a lot of heavy lifting' is sarcastic — the word is being made to hide a harsh reality","the blunt '400 people have just been sacked' contrasts with the euphemism, exposing the human cost"],"l":3,"h":"Think about the inverted commas and the irony."}]},
"ruae_imagery":{"name":"Imagery","area":"ruae","questions":[{"q":"What is a metaphor?","o":["A comparison saying one thing IS another","A comparison using \"like\" or \"as\"","Giving human qualities to an object","Exaggeration for effect"],"l":1,"e":"E.g. \"The classroom was a zoo.\" Metaphors make a direct comparison."},{"q":"What is a simile?","o":["A comparison using \"like\" or \"as\"","A direct comparison without \"like\"","A repeated sound","A contradiction"],"l":1,"e":"E.g. \"The crowd moved like a slow river.\""},{"q":"What is personification?","o":["Giving human qualities or actions to something non-human","Comparing two humans","Using animal sounds","Addressing the reader directly"],"l":1,"e":"E.g. \"The wind howled its anger.\""},{"q":"What is the recognised method for analysing imagery in RUAE?","o":["Explain the literal root of the image, then how it applies to the subject","Name the image and say it is effective","Count the images in the paragraph","Explain what the image rhymes with"],"l":2,"e":"Marking instructions reward showing the link: what the image literally means → what that suggests about the subject."},{"q":"\"The housing market is a game of musical chairs, and the music is about to stop.\" What does the image suggest?","o":["When prices fall, some people will be left with no seat — losers in a sudden scramble","Buying a house is fun","Houses are cheap","Music affects house prices"],"l":2,"e":"In musical chairs, when the music stops someone is left out — so a sudden end will leave some buyers stranded."},{"q":"\"Social media is a hall of mirrors.\" This suggests social media…","o":["distorts reality and reflects back exaggerated versions of ourselves","is entertaining and harmless","is a place to see friends","is made of glass"],"l":2,"e":"A hall of mirrors gives distorted reflections — so online images are warped and unreliable."},{"q":"\"The bill was rushed through Parliament like a getaway car.\" The simile suggests…","o":["the bill was passed hastily and suspiciously, as if avoiding scrutiny","the bill was popular","MPs drive fast","the bill was about cars"],"l":2,"e":"A getaway car flees a crime — so speed plus guilt/evasion."},{"q":"\"Tourism is the golden goose the island dare not kill.\" What does the image convey?","o":["Tourism is a valuable source of wealth that must not be destroyed by greed or over-use","Tourists bring geese","Tourism is cruel","The island is rich in gold"],"l":3,"e":"From the fable: killing the goose that lays golden eggs destroys the source of wealth."},{"q":"\"The town centre is a ghost town after six o'clock.\" This suggests…","o":["it is deserted and lifeless","it is haunted","it is lively","it is historic"],"l":2,"e":"\"Ghost town\" connotes emptiness, desertion and decline."},{"q":"Which is an example of an extended metaphor?","o":["An image developed over several sentences, e.g. a debate described throughout as a boxing match","A single simile","A list of adjectives","A rhetorical question"],"l":2,"e":"Extended imagery sustains one comparison across a passage, strengthening its effect."},{"q":"\"The government has opened Pandora's box.\" The writer suggests…","o":["a decision has released many problems that cannot be put back","the government has found treasure","the decision was secret","the government is generous"],"l":3,"e":"In myth, opening Pandora's box released evils into the world."},{"q":"\"Hospitals are at breaking point.\" This image suggests…","o":["they are under so much pressure they are close to collapse","they are being repaired","they are closed","they are excellent"],"l":2,"e":"Breaking point — literally where a material snaps — conveys severe strain."},{"q":"Which phrase is a simile?","o":["as stubborn as a mule","the stubborn mule","a mule of a man","mulish"],"l":1,"e":"Only \"as stubborn as a mule\" uses \"as … as\"."},{"q":"In an imagery answer, which comment is most likely to gain 2 marks?","o":["\"Just as a tsunami is an unstoppable wave that destroys everything, the flood of complaints overwhelmed the company\"","\"The tsunami image is effective and vivid\"","\"This is a metaphor\"","\"It makes me picture a wave\""],"l":3,"e":"Root → application, with insight. Naming or \"vivid\" earns nothing."},{"q":"Read this sentence:\n\n\"Smartphones have become the dummy we reach for whenever life threatens to be boring.\"\n\nAnalyse the writer's use of imagery.","m":2,"p":["a dummy is given to a baby to soothe/quieten it","so the writer suggests we use phones for instant comfort / to avoid discomfort, like infants","this conveys the writer's critical / mocking attitude — our dependence is childish and unthinking"],"l":1,"h":"What is a dummy? Who uses one, and why?"},{"q":"Read this paragraph:\n\n\"Fast fashion is a conveyor belt that never stops. Clothes tumble off it in their millions, worn once and dumped, until the landfill sites of the world are choked with polyester. The industry feeds on our appetite for novelty like a fire fed with paper: brief, bright and leaving nothing but ash.\"\n\nBy referring to at least two examples, analyse how the writer uses imagery to convey criticism of fast fashion.","m":4,"p":["'conveyor belt' — a relentless, mechanical factory process — suggests fashion is mass-produced endlessly without thought","'tumble off it in their millions' — like goods falling uncontrolled — suggests vast, careless over-production","'choked' — personification of suffocation — suggests landfill is overwhelmed / the planet is being harmed","'like a fire fed with paper' — paper burns quickly and is soon gone — suggests our desire for new clothes is fleeting","'nothing but ash' — suggests waste and destruction are all that remain"],"l":2,"h":"Root of each image → how it applies."}]},
"ruae_sentence":{"name":"Sentence Structure & Punctuation","area":"ruae","questions":[{"q":"Which of these is a feature of sentence structure?","o":["Repetition, lists, short sentences, questions, inversion","Connotation of a single word","Metaphor","Alliteration"],"l":1,"e":"Sentence structure is about how a sentence is built and ordered."},{"q":"How should you comment on a short sentence?","o":["Explain how its brevity creates emphasis/impact on the specific idea it contains","Say \"it is short so it is effective\"","Count the words","Say it makes you want to read on"],"l":2,"e":"Always tie the feature to the content: what is being emphasised and why."},{"q":"What effect does a list often have?","o":["It can suggest the number, range or variety of something — or build up to a climax","It always slows the reader down","It shows the writer is confused","It removes emphasis"],"l":2,"e":"Comment on what the list conveys, e.g. the scale of a problem."},{"q":"What is a climax in sentence structure?","o":["Ideas arranged in rising order of importance, ending on the strongest","A sentence ending in a question","A very short sentence","A sentence in brackets"],"l":2,"e":"The final item gains emphasis by its position."},{"q":"What is an anticlimax?","o":["A build-up that ends on something trivial or deflating, often for humour","A sentence with no verb","A repeated word","A colon followed by a list"],"l":2,"e":"E.g. \"He conquered empires, built cities and once lost a sock.\""},{"q":"What is the usual function of a colon?","o":["To introduce an explanation, expansion, list or example","To show a question","To show strong emotion","To join two equal clauses with no link"],"l":2,"e":"The colon \"opens a door\" to what follows."},{"q":"What is the function of a semicolon between two clauses?","o":["It links two closely related or balanced/contrasting ideas","It introduces a list","It shows speech","It ends a paragraph"],"l":2,"e":"Semicolons can create balance or contrast between two clauses."},{"q":"Parenthesis (brackets, dashes or commas) is used to…","o":["add extra information or a comment, often an aside revealing the writer's attitude","end a sentence","show a quotation","introduce speech"],"l":2,"e":"Parenthetical asides can be ironic, explanatory or emphatic."},{"q":"A single dash often…","o":["introduces a dramatic, surprising or emphatic addition or a pause","separates items in a list","indicates a question","shows a quotation"],"l":2,"e":"E.g. \"There was only one problem — nobody came.\""},{"q":"Inverted commas around a single word (not speech) usually suggest…","o":["the writer is distancing themselves from the term, often sarcastically","the word is important","the word is a quotation from Shakespeare","the word is foreign"],"l":2,"e":"E.g. the 'experts' — suggests scepticism."},{"q":"What is inversion?","o":["Changing the normal word order to place emphasis on a word at the start or end","Turning a statement into a question","Repeating a phrase","Using the opposite meaning"],"l":2,"e":"E.g. \"Gone are the days of free parking\" puts emphasis on \"Gone\"."},{"q":"A rhetorical question is…","o":["a question asked for effect, not expecting an answer","a question in a survey","a question with two answers","any question at the end of a paragraph"],"l":2,"e":"It engages the reader or implies an obvious answer."},{"q":"\"Fewer buses. Higher fares. Longer waits.\" What does this structure achieve?","o":["Three blunt minor sentences in parallel hammer home the scale of decline","It shows the writer has run out of ideas","It creates a calm tone","It introduces a quotation"],"l":3,"e":"Tricolon of minor sentences — emphatic, cumulative criticism."},{"q":"What is a minor sentence?","o":["A sentence without a main verb, e.g. \"What a disaster.\"","A sentence with lots of clauses","A sentence in the past tense","A sentence with a colon"],"l":2,"e":"Minor sentences are often used for impact or a conversational tone."},{"q":"What is antithesis?","o":["Placing contrasting ideas in balanced phrases","Repeating the first word of clauses","Exaggeration","A comparison using \"like\""],"l":2,"e":"E.g. \"Not a revolution, but a retreat.\""},{"q":"Repetition of \"We were told…\" at the start of three sentences mainly…","o":["emphasises how often people were misled, building anger","adds variety","shows the writer forgot","creates a happy tone"],"l":3,"e":"Anaphora (repeated openings) creates emphasis and rhythm."},{"q":"An ellipsis (…) in a passage may suggest…","o":["something left unsaid, a trailing off, or a pause before a twist","the end of the passage","a list","a formal tone"],"l":2,"e":"Comment on what the pause or omission implies."},{"q":"A sentence ends with the single word \"Nothing.\" after a long build-up. This positioning…","o":["creates an anticlimax/bathos that emphasises the lack of result","introduces a list","creates suspense about what comes next","shows formality"],"l":3,"e":"A blunt end after build-up throws weight on the final word."},{"q":"Read this sentence:\n\n\"They promised jobs; they delivered car parks.\"\n\nAnalyse how the sentence structure conveys the writer's criticism.","m":2,"p":["semicolon creates a balanced structure that sets the promise against the reality","parallel 'They promised… they delivered…' highlights the gap between what was pledged and what happened","ending on 'car parks' creates an anticlimax — something trivial/disappointing compared with jobs — mocking the failure"],"l":1,"h":"Think semicolon, balance and contrast."},{"q":"Read this paragraph:\n\n\"We were told the new system would be quicker. We were told it would be cheaper. We were told — repeatedly, confidently, by people who should have known better — that it would never crash. It crashed on the first morning.\"\n\nBy referring to at least two features of sentence structure, analyse how the writer conveys anger.","m":4,"p":["repetition of 'We were told' emphasises how often the public were given promises — builds frustration","the parenthesis between dashes adds a sarcastic aside stressing the promisers' arrogance/responsibility","list 'repeatedly, confidently…' builds up the weight of the false assurances","the short final sentence is blunt and abrupt, creating an anticlimax that exposes the failure","positioning 'on the first morning' at the end emphasises how quickly the promises collapsed"],"l":2,"h":"Repetition, parenthesis, short final sentence."}]},
"ruae_tone":{"name":"Tone","area":"ruae","questions":[{"q":"What is tone?","o":["The writer's attitude/feeling conveyed through language","The loudness of a text","The topic of a passage","The length of sentences"],"l":1,"e":"Tone can be sarcastic, angry, nostalgic, humorous, sincere, etc."},{"q":"To identify tone you should…","o":["name it precisely and show how specific language creates it","just name the tone","describe the topic","say the writer sounds emotional"],"l":2,"e":"Tone questions need a named tone AND analysis of the language that creates it."},{"q":"Saying the opposite of what you mean to mock someone is…","o":["sarcasm/irony","nostalgia","bathos","understatement"],"l":2,"e":"Sarcasm is a cutting form of irony."},{"q":"\"Oh brilliant — another meeting about meetings.\" The tone is…","o":["sarcastic","celebratory","nostalgic","formal"],"l":2,"e":"Praise (\"brilliant\") applied to something obviously pointless signals sarcasm."},{"q":"\"I remember the long summer evenings of the Seventies, when we roamed the fields until dark.\" The tone is most likely…","o":["nostalgic","angry","sarcastic","clinical"],"l":2,"e":"Fond, wistful memory of the past = nostalgia."},{"q":"What is a colloquial tone?","o":["Informal, conversational language, like everyday speech","Highly technical language","Old-fashioned language","Poetic language"],"l":2,"e":"Colloquial features: slang, contractions, direct address, chatty asides."},{"q":"Why might a serious writer suddenly use colloquial language?","o":["To create humour, closeness with the reader, or to puncture pomposity","Because they forgot the rules","To make the passage longer","To sound more formal"],"l":3,"e":"A shift in register is deliberate — comment on its effect."},{"q":"Understatement is…","o":["presenting something as less important or serious than it is","exaggerating for effect","repeating a word","asking a question"],"l":2,"e":"E.g. calling a hurricane \"a bit breezy\" — often ironic."},{"q":"Hyperbole is…","o":["deliberate exaggeration","a gentle understatement","a comparison using \"as\"","a contradiction"],"l":2,"e":"E.g. \"I've told you a million times.\""},{"q":"Bathos is…","o":["a sudden drop from the serious or elevated to the trivial, often for comic effect","intense sadness","a formal register","a long list"],"l":3,"e":"E.g. \"He gave his life for his country — and his lunchbox.\""},{"q":"Which language features often create a persuasive tone?","o":["Direct address, rhetorical questions, emotive language, inclusive \"we\"","Passive voice, statistics only, technical terms","Footnotes and references","Dialogue between characters"],"l":2,"e":"Persuasive tone aims to win the reader over."},{"q":"A writer describes politicians as \"our gallant leaders\" while criticising their decisions. \"gallant\" here creates…","o":["an ironic/mocking tone","a sincere, admiring tone","a nostalgic tone","a formal neutral tone"],"l":3,"e":"Heroic vocabulary applied to people the writer criticises is ironic."},{"q":"What is a \"dismissive\" tone?","o":["Treating something as unworthy of serious attention","Being very enthusiastic","Being sad","Being neutral"],"l":2,"e":"Dismissive tone belittles an idea or person."},{"q":"Read these sentences:\n\n\"The council, in its infinite wisdom, has decided that the town's only swimming pool is a luxury we can no longer afford. Never mind the children who will never learn to swim. Never mind the elderly who rely on it. The books must balance.\"\n\nAnalyse how the writer creates a sarcastic tone.","m":2,"p":["'in its infinite wisdom' is mock praise — the writer means the opposite, ridiculing the council's decision","repetition of 'Never mind…' sarcastically echoes the council's indifference to people's needs","the short, flat 'The books must balance.' mimics the cold, bureaucratic reasoning, exposing its heartlessness"],"l":2,"h":"Name the tone and show the language that creates it."},{"q":"Read this paragraph:\n\n\"Let us all take a moment to applaud the brave executives who, having steered the company onto the rocks, have nobly agreed to accept only a modest seven-figure bonus. Truly, their sacrifice moves me to tears. The workers who lost their pensions will, I'm sure, be comforted.\"\n\nBy referring to at least two examples, analyse how the writer's language conveys contempt for the executives.","m":4,"p":["'applaud the brave executives' — ironic praise; they have done nothing brave","'steered the company onto the rocks' — shipwreck metaphor showing reckless, incompetent leadership","'nobly'/'modest seven-figure bonus' — contradiction exposes greed; a huge sum called modest","'Truly, their sacrifice moves me to tears' — exaggerated mock sincerity / sarcasm","'will, I'm sure, be comforted' — sarcastic aside highlighting the injustice to the workers"],"l":3,"h":"Irony, imagery, word choice, tone."}]},
"ruae_structure":{"name":"Structure & Link Questions","area":"ruae","questions":[{"q":"A \"link\" question asks you to…","o":["show how a sentence connects what has gone before with what follows","summarise the passage","identify the tone","find the main metaphor"],"l":1,"e":"Link sentences/paragraphs act as bridges in the argument."},{"q":"What is the recognised method for a link question?","o":["Quote/refer to the part that links back and show its connection to the previous idea, then the part that looks forward to the next idea","Explain the meaning of every word","Name the tone","Give your opinion"],"l":2,"e":"Two halves: back-reference + forward-reference."},{"q":"\"Yet these benefits come at a price.\" In a link question, \"these benefits\" refers…","o":["back to the advantages just discussed","forward to the next paragraph's topic","to the writer's conclusion","to the title"],"l":2,"e":"\"These\" points backwards; \"come at a price\" introduces the drawbacks to follow."},{"q":"In the sentence above, which words introduce the new direction of the argument?","o":["come at a price","these","Yet these","benefits"],"l":2,"e":"\"Come at a price\" signals that disadvantages/costs are about to be discussed; \"Yet\" signals the turn."},{"q":"Which word typically signals a change of direction in an argument?","o":["However","Furthermore","Moreover","Similarly"],"l":2,"e":"\"However\" signals contrast; the others add or compare."},{"q":"What does a question asking about \"the function of\" a paragraph want?","o":["What job it does in the structure of the argument, e.g. introduce a counter-argument, give an example, conclude","The meaning of the words in it","The tone","Your opinion"],"l":2,"e":"The specification lists \"explain (the function of)\" for understanding of structure."},{"q":"Why might a writer open with an anecdote?","o":["To engage the reader with a personal, concrete example that leads into the wider issue","Because anecdotes are required","To show off","To end the argument"],"l":2,"e":"Anecdotes humanise an issue and hook the reader."},{"q":"A conclusion that returns to an image used in the opening is said to be…","o":["cyclical — it gives a sense of completeness and reinforces the main point","an anticlimax","a counter-argument","a digression"],"l":3,"e":"Cyclical structure ties the argument together."},{"q":"What is a \"counter-argument\"?","o":["An opposing view the writer raises (often to rebut it)","The writer's main point","A summary","A statistic"],"l":2,"e":"Acknowledging and refuting the other side strengthens an argument."},{"q":"An \"effective conclusion\" question asks you to show…","o":["how the ending links to/sums up ideas or language from earlier in the passage","that the conclusion is the shortest paragraph","that the writer changes topic","how many paragraphs there are"],"l":3,"e":"Refer to specific earlier ideas/techniques the ending echoes or resolves."},{"q":"A topic sentence in a paragraph…","o":["states the main idea of that paragraph","gives a statistic","ends the paragraph","is always a question"],"l":2,"e":"Spotting topic sentences helps you track the argument for the final question."},{"q":"Read the end of one paragraph and the start of the next:\n\n\"…and so, for most of the twentieth century, the railway was the beating heart of the town.\n\nThat heart stopped in 1964. Within a decade the station was rubble and the hotel a care home.\"\n\nExplain how the sentence \"That heart stopped in 1964.\" helps to link the two paragraphs.","m":2,"p":["'That heart' refers back to the image of the railway as 'the beating heart' of the town / its importance","'stopped in 1964' introduces the new idea of the railway's closure and the town's decline that follows"],"l":2,"h":"Back + forward."},{"q":"Read this paragraph, which comes after a writer has praised electric cars:\n\n\"And yet. The batteries that power these vehicles depend on metals dug from the ground in some of the poorest countries on earth, often by children. Clean on the motorway; filthy at the mine.\"\n\nAnalyse how the writer uses structure to signal a change in the line of argument.","m":3,"p":["'And yet.' as a one-line minor sentence creates a dramatic pause/turning point","'yet' signals a contrast with the praise of electric cars before","the semicolon in 'Clean on the motorway; filthy at the mine' creates a balanced antithesis showing the hidden cost","positioning the reality of mining after the praise exposes the drawbacks the earlier paragraph ignored"],"l":2,"h":"Minor sentence, positioning, balance."}]},
"ruae_evaluation":{"name":"Evaluation & the Final 5-Mark Question","area":"ruae","questions":[{"q":"How many marks is the final RUAE question on both passages worth?","o":["5","3","8","10"],"l":1,"e":"The question on both passages is worth 5 marks."},{"q":"What does the final question ask you to do?","o":["Identify key areas on which the writers agree or disagree, supported by evidence from both passages","Analyse the language of Passage 2","Write a critical essay","Give your own opinion"],"l":2,"e":"The specimen paper asks you to \"identify three key areas on which they agree\" (or disagree), referring to both passages."},{"q":"According to the specimen marking instructions, what earns 3 marks in the final question?","o":["Identifying three key areas of agreement/disagreement","One area with a detailed quotation","Two areas with evidence","Three quotations from Passage 2"],"l":2,"e":"3 marks for three key areas; 4 with appropriate evidence; 5 with detailed/insightful evidence."},{"q":"What do you need for full marks (5) in the final question?","o":["Three key areas with detailed/insightful supporting evidence from both passages","Five areas listed","A conclusion with your view","Analysis of techniques"],"l":2,"e":"Detailed use of evidence from both passages lifts 3 areas to 5 marks."},{"q":"Can you answer the final question in bullet points?","o":["Yes — continuous prose or a series of developed bullet points","No — it must be an essay","Only for 2 marks","Only if the question is about disagreement"],"l":2,"e":"The specimen paper explicitly allows developed bullet points."},{"q":"What is a \"key area\" in the final question?","o":["A main idea/stance the writers share (or differ on), stated at the level of the overall argument","A single word both writers use","A technique both writers use","A paragraph number"],"l":3,"e":"Key areas are big ideas, e.g. \"both feel trees connect us to the past\", not matching vocabulary."},{"q":"What is the best preparation for the final question while reading Passage 2?","o":["Note each main idea of Passage 2 and whether Passage 1 agrees or disagrees","Highlight every metaphor","Count the paragraphs","Skip Passage 2 until the end"],"l":2,"e":"Mapping ideas as you read makes the final question quicker."},{"q":"Roughly how long should you allow for the final 5-mark question?","o":["About 15 minutes, including reading Passage 2","2 minutes","45 minutes","No time — leave it out"],"l":2,"e":"You must read Passage 2 and plan — candidates often run short of time here."},{"q":"An \"evaluate\" question in RUAE asks you to…","o":["judge how effective a technique, part or the whole text is, with analysis to support your view","summarise the passage","give your feelings about the topic","list techniques"],"l":2,"e":"Evaluation = analysis + a judgement of effectiveness."},{"q":"A question asks how effective the final paragraph is as a conclusion. The strongest answer will…","o":["analyse specific language/ideas in the ending and show how they link back to earlier parts of the passage","say \"it is effective because it sums up\"","quote the whole paragraph","describe your own opinion on the topic"],"l":3,"e":"Show the connection with concrete references."},{"q":"Which is a good opening for a final-question key area?","o":["\"Both writers agree that zoos have changed for the better: Passage 1… while Passage 2…\"","\"In my opinion zoos are good.\"","\"Passage 2 uses lots of imagery.\"","\"The writers are different.\""],"l":2,"e":"State the area, then support from each passage."},{"q":"If the final question asks about DISAGREEMENT, each key area should…","o":["show what each writer believes on the same issue and how they differ","list the techniques each uses","focus on one writer only","quote the conclusions only"],"l":3,"e":"Each area must cover both stances on a shared issue."},{"q":"Passage A: \"Libraries are no longer just about books. They are warm, free spaces where anyone — the jobseeker, the student, the lonely pensioner — can sit without being asked to buy anything.\"\n\nPassage B: \"In a world where almost every space wants your money, the public library is a rare refuge. And while the shelves still matter, today's library lends laptops, runs coding clubs and helps people fill in benefit forms.\"\n\nIdentify key areas on which the writers agree. Support your points with reference to both extracts.","m":3,"p":["Libraries offer more than books — A: 'no longer just about books'; B: lends laptops, coding clubs, help with forms","Libraries are free/non-commercial spaces — A: 'without being asked to buy anything'; B: 'rare refuge' where other spaces 'want your money'","Libraries serve the whole community / people in need — A: jobseeker, student, pensioner; B: help with benefit forms"],"l":2,"h":"Look for big shared ideas, not shared words."}]},
"ce_paper":{"name":"Critical Reading Paper Overview","area":"ce","questions":[{"q":"How many marks is the Higher Critical Reading paper worth?","o":["40","30","20","50"],"l":1,"e":"Critical Reading is 40 marks (40% of the course award): 20 for the Scottish text and 20 for the critical essay."},{"q":"How long is the Higher Critical Reading paper?","o":["1 hour 45 minutes","1 hour 30 minutes","2 hours","1 hour 15 minutes"],"l":1,"e":"The course specification gives 1 hour 45 minutes."},{"q":"How many marks is Section 2 (the critical essay) worth?","o":["20","10","25","30"],"l":1,"e":"Each section of Critical Reading carries 20 marks."},{"q":"What is the key rule about genres across the two sections?","o":["You must use a different genre in Section 2 from the one you used in Section 1","You must use the same genre","You must write on poetry once","There is no rule"],"l":2,"e":"Candidates must cover a different genre in each section and cannot use the same text twice."},{"q":"If you answer on a Carol Ann Duffy poem in Section 1, which of these could you write your critical essay on?","o":["A play or a novel","Another Duffy poem","Any poem","Duffy's poems again from a different angle"],"l":2,"e":"Poetry is used in Section 1, so Section 2 must be a different genre (drama, prose, film & TV drama or language)."},{"q":"Which genres can appear in Section 2?","o":["Drama, prose fiction, prose non-fiction, poetry, film and TV drama, language","Drama, prose and poetry only","Scottish texts only","Poetry and film only"],"l":2,"e":"The specification lists all six contexts (prose fiction and non-fiction count as one genre: prose)."},{"q":"How many essay questions do you choose from in your chosen genre section?","o":["Choose one question from a choice of three (in each genre part)","You must answer all three","One fixed question","Two questions"],"l":2,"e":"The specification: \"one question from a choice of three\"."},{"q":"Roughly how long should you spend on the critical essay?","o":["About 45–50 minutes","20 minutes","90 minutes","15 minutes"],"l":2,"e":"With 1 h 45 min for two 20-mark sections, splitting the time roughly evenly (plus planning) is sensible."},{"q":"Which phrase is attached to every critical essay question?","o":["\"By referring to appropriate techniques…\"","\"Using your own words…\"","\"Look at both passages…\"","\"With reference to the extract…\""],"l":2,"e":"The specification says the command words are always accompanied by an instruction to refer to appropriate techniques."},{"q":"Which main command words are used in critical essay questions?","o":["Discuss how / explain how","Identify / summarise","Analyse / evaluate the passage","Describe / define"],"l":2,"e":"The specification lists \"discuss how\" and \"explain how\"."},{"q":"Most critical essay questions have two parts. What does the second part usually ask?","o":["How the feature contributes to your appreciation of the text as a whole","For a summary of the plot","For your favourite quotation","For a personal anecdote"],"l":3,"e":"E.g. \"…briefly explain the nature of the conflict and discuss how this contributes to your appreciation of the play as a whole.\""},{"q":"When must you decide which texts you will use for the critical essay?","o":["Before the exam — prepare at least one text thoroughly in a genre different from your Scottish text","In the exam, after reading the questions","After the Scottish text section","It doesn't matter"],"l":2,"e":"You need a well-known, prepared text; pupils often prepare two to keep choice."}]},
"ce_structure":{"name":"Critical Essay Structure","area":"ce","questions":[{"q":"What should the introduction of a critical essay do?","o":["Name the text and writer, address the key words of the question and outline your line of argument","Tell the whole story","Give your life story","List every technique you know"],"l":1,"e":"Introduce TAG (title, author, genre), link to the question, and signpost the argument."},{"q":"What is a \"line of thought\" or \"line of argument\"?","o":["A clear, consistent response to the question that runs through every paragraph","A list of quotations","The order of events in the text","A summary of the plot"],"l":2,"e":"Markers reward a critical line of thought sustained throughout."},{"q":"A strong topic sentence should…","o":["make a point that answers the question, using its key words","retell what happens next","contain a long quotation","ask a rhetorical question"],"l":2,"e":"Topic sentences keep each paragraph relevant to the task."},{"q":"Which paragraph structure helps a critical essay most?","o":["Point – evidence – analysis – evaluation, linked back to the question","Quotation – quotation – quotation","Plot – plot – opinion","Introduction – conclusion"],"l":2,"e":"The marking grid rewards knowledge, analysis and evaluation, and focus on the question."},{"q":"What is \"evaluation\" in a critical essay?","o":["Your judgement of how effectively the writer achieves an effect / why it matters to the text as a whole","Retelling the story","Saying you liked the book","Listing techniques"],"l":2,"e":"The grid looks for an evaluative stance \"with respect to the text and the task\"."},{"q":"Which is the best way to use quotations in an essay?","o":["Short, embedded quotations followed by analysis of key words","Long quotations of several lines without comment","No quotations at all","Quotations only in the conclusion"],"l":2,"e":"Embed brief quotes and analyse them; long unexplained quotes add nothing."},{"q":"Which is the strongest piece of analysis?","o":["\"The verb 'clawed' suggests a desperate, almost animal struggle, conveying how far poverty has dehumanised the family.\"","\"The writer uses good word choice here.\"","\"This quote shows what happened next.\"","\"This makes the reader want to read on.\""],"l":3,"e":"It identifies the feature, explores connotation and links to meaning/theme."},{"q":"What should the conclusion of a critical essay do?","o":["Return to the question, sum up the argument and give a final evaluation of the text as a whole","Introduce a new character","Retell the ending","Thank the reader"],"l":2,"e":"A conclusion re-states your line of thought and evaluates."},{"q":"Why is \"retelling the story\" a problem?","o":["It shows knowledge but not analysis or evaluation, so it limits the mark","It is too short","It is always wrong","Markers don't know the text"],"l":2,"e":"Plot summary alone cannot reach the higher bands."},{"q":"What does \"turn of the question\" mean?","o":["The specific angle the question asks you to address (e.g. HOW the conflict contributes to the whole)","The first sentence of your essay","The page of the exam","The genre heading"],"l":2,"e":"Keep returning to the question's exact wording in every paragraph."},{"q":"A question asks about a \"turning point\". Which plan best fits?","o":["Explain what the turning point is, analyse how it is presented, and show how it changes characters/themes/the text as a whole","Describe every scene in order","Write only about the ending","Discuss the writer's biography"],"l":3,"e":"Explain the feature, then its contribution to the whole."},{"q":"How many main body paragraphs is typical for a strong Higher essay?","o":["About four to six developed paragraphs","One long paragraph","Fifteen short paragraphs","No paragraphs — continuous text"],"l":2,"e":"Quality matters more than quantity, but 4–6 developed paragraphs is typical."},{"q":"What is a \"linking sentence\" at the end of a body paragraph for?","o":["To tie the point back to the question and the text as a whole","To introduce a new quotation","To change the subject","To summarise the plot"],"l":2,"e":"Linking back shows focus on the demands of the question."},{"q":"Plan the introduction for this question on a novel or play you know:\n\n\"Choose a play in which a character faces a significant challenge or difficulty. By referring to appropriate techniques, briefly explain the nature of the challenge and discuss how this contributes to your appreciation of the play as a whole.\"\n\nWrite an introduction (3–5 sentences).","m":4,"p":["Names the text and the writer accurately","Identifies the character and the nature of the challenge/difficulty clearly","Uses the key words of the question ('challenge', 'appreciation of the play as a whole')","Signposts the line of argument / the main points or techniques the essay will cover (e.g. characterisation, key scene, climax, theme)"],"l":2,"h":"Title, writer, genre, character, challenge, line of thought."},{"q":"Write one body paragraph (about 150 words) for a critical essay on any text you know, using the PEAE structure (point, evidence, analysis, evaluation).","m":4,"p":["Clear topic sentence that makes a point relevant to a question","Accurate, short evidence — quotation or close reference","Analysis of a specific technique (word choice, imagery, structure, camera work…) and its effect","Evaluation linking the point to the text as a whole / theme / the question"],"l":3,"h":"Remember the question focus."}]},
"ce_marking":{"name":"Essay Marking Criteria & Technical Accuracy","area":"ce","questions":[{"q":"Out of how many marks is the critical essay marked?","o":["20","25","10","30"],"l":1,"e":"The critical essay is marked out of 20 using a supplementary marking grid."},{"q":"What is the top band in the critical essay marking grid?","o":["20–19","25–23","20–17","15–13"],"l":2,"e":"Bands: 20–19, 18–16, 15–13, 12–10, 9–6, 5–0."},{"q":"If an essay does NOT meet minimum standards of technical accuracy (or relevance), what is the maximum mark?","o":["9","12","0","15"],"l":2,"e":"The specimen marking instructions: award a maximum of 9 marks if minimum standards are not achieved."},{"q":"What does \"technical accuracy\" mean in the marking grid?","o":["Few errors in spelling, grammar, sentence construction, punctuation and paragraphing; understood at first reading","Using lots of technical terms","Knowing the dates of the text","Writing more than 1,000 words"],"l":2,"e":"The grid's technical accuracy requirement."},{"q":"Which three areas does the essay grid assess, besides technical accuracy?","o":["Knowledge and understanding, analysis, evaluation","Spelling, handwriting, length","Plot, character, setting","Quotations, dates, context"],"l":2,"e":"The grid has rows for knowledge & understanding, analysis and evaluation."},{"q":"Which phrase describes analysis in the 20–19 band?","o":["\"perceptive analysis of the effect of features of language/filmic techniques\"","\"adequate analysis\"","\"clear analysis\"","\"limited analysis\""],"l":2,"e":"Perceptive (20–19), detailed (18–16), clear (15–13), adequate (12–10), limited (9–6)."},{"q":"Which describes evaluation in the 18–16 band?","o":["\"engaged evaluative stance with respect to the text and the task\"","\"committed, evaluative stance\"","\"clear evaluative stance\"","\"very little evidence of an evaluative stance\""],"l":2,"e":"Committed (20–19), engaged (18–16), clear (15–13)."},{"q":"Within a band, when should a marker award the highest mark in the range?","o":["When the evidence almost matches the level above","When the essay is long","Always","When the handwriting is neat"],"l":3,"e":"Best-fit guidance: almost matches the level above → top of range; just meets → bottom; otherwise middle."},{"q":"Marking is described as \"holistic\". This means…","o":["the marker judges the essay as a whole, focusing on strengths","marks are deducted for each error","only the introduction is marked","each paragraph gets a set mark"],"l":2,"e":"Assessment is holistic and focuses on strengths."},{"q":"Which mistake is most likely to hurt technical accuracy?","o":["Writing \"it's\" for \"its\", missing apostrophes, comma splices and no paragraphs","Using a semi-colon correctly","Writing in the present tense","Using the word \"furthermore\""],"l":2,"e":"Frequent basic errors that impede understanding take an essay below the minimum standard."},{"q":"Which tense is conventional when writing about events in a literary text?","o":["Present tense (\"Macbeth kills Duncan\")","Future tense","Past perfect only","Any tense, changing often"],"l":2,"e":"The \"literary present\" keeps analysis clear and consistent."},{"q":"The 15–13 band asks for \"clear knowledge and understanding\" and \"clear textual evidence\". What does 18–16 add?","o":["\"Secure\" knowledge and \"detailed\" textual evidence, coherently structured","Longer quotations","More plot","A better conclusion only"],"l":3,"e":"Moving up a band means secure, detailed, coherent work."},{"q":"Should you write about the film version when answering on a novel?","o":["No — write about the text you studied in its own genre","Yes, it's the same thing","Only for 5 marks","Only if you mention the director"],"l":2,"e":"Film and TV drama is its own genre; answer on the text as written."}]},
"ce_drama":{"name":"Drama Essays & Terminology","area":"ce","questions":[{"q":"What are stage directions?","o":["Instructions in a script about setting, movement, lighting, sound and how lines are delivered","The lines spoken by characters","The list of characters only","The audience's reactions"],"l":1,"e":"Stage directions are crucial evidence in drama essays."},{"q":"A long speech by one character to others on stage is…","o":["a monologue","a soliloquy","an aside","a duologue"],"l":1,"e":"A monologue is addressed to other characters; a soliloquy is spoken alone, revealing private thoughts."},{"q":"A speech made by a character alone on stage, revealing thoughts to the audience, is…","o":["a soliloquy","an aside","a chorus","a prologue"],"l":1,"e":"E.g. Hamlet's \"To be, or not to be\"."},{"q":"A brief remark to the audience that other characters on stage cannot hear is…","o":["an aside","a soliloquy","a monologue","a cue"],"l":2,"e":"Asides create dramatic irony and intimacy with the audience."},{"q":"Dramatic irony occurs when…","o":["the audience knows something a character does not","a character is sarcastic","the ending is happy","the play is set in the past"],"l":2,"e":"It builds tension and engagement."},{"q":"The climax of a play is…","o":["the point of highest tension, where the central conflict comes to a head","the opening scene","the final line","the list of characters"],"l":2,"e":"Climax is a key feature named in drama essay rubrics."},{"q":"The denouement or resolution is…","o":["the final part where outcomes are revealed and loose ends tied up","the first scene","an interval","a subplot"],"l":2,"e":"It follows the climax."},{"q":"A \"tragic hero\" is usually…","o":["a central figure of high standing whose flaw leads to downfall","a villain","a minor comic character","the narrator"],"l":2,"e":"E.g. Macbeth's ambition."},{"q":"\"Hamartia\" means…","o":["the fatal flaw of a tragic hero","the play's setting","the comic relief","the stage set"],"l":2,"e":"From Greek tragedy (Aristotle)."},{"q":"Which features does the drama rubric suggest you might refer to?","o":["Characterisation, key scene(s), structure, climax, theme, plot, conflict, setting","Rhyme, metre, stanza","Camera angles, editing","Statistics and evidence"],"l":2,"e":"The specimen paper's drama introduction lists these."},{"q":"A subplot is…","o":["a secondary storyline that supports or contrasts with the main plot","a hidden message","the ending","the stage directions"],"l":2,"e":"Subplots often mirror main themes."},{"q":"Why is \"key scene\" a strong focus for a drama essay?","o":["You can analyse dialogue, stage directions and staging in detail, then show its importance to the whole play","Because it is the shortest part","Because markers prefer short essays","Because you can avoid quotations"],"l":3,"e":"One scene, analysed closely and linked to themes, gives depth."},{"q":"Conflict in drama can be…","o":["between characters, within a character, or between a character and society","only physical fighting","only between two families","only at the end"],"l":2,"e":"Name the type of conflict precisely."},{"q":"\"Foil\" means…","o":["a character whose contrasting qualities highlight those of another","the stage set","a sword fight","the playwright's notes"],"l":2,"e":"E.g. a cautious friend highlighting a hero's recklessness."}]},
"ce_prose":{"name":"Prose Essays & Terminology","area":"ce","questions":[{"q":"A first-person narrator…","o":["tells the story as \"I\", often a character in it","is never involved in the story","knows everything about everyone","is always the author"],"l":1,"e":"First-person narration gives intimacy but limited perspective."},{"q":"An omniscient narrator…","o":["knows the thoughts and feelings of all characters","only knows one character's thoughts","is always unreliable","speaks in the second person"],"l":2,"e":"Third-person omniscient narration can move between characters' minds."},{"q":"An unreliable narrator is…","o":["a narrator whose account cannot be fully trusted","a narrator who is boring","a narrator who dies","any third-person narrator"],"l":2,"e":"Readers must question what they are told."},{"q":"Foreshadowing is…","o":["hints of events to come","a flashback","the ending","a symbol of death"],"l":2,"e":"It builds suspense and coherence."},{"q":"A flashback is…","o":["a scene that moves back in time from the main narrative","a prediction","a dream sequence only","the final chapter"],"l":2,"e":"Flashbacks reveal background and motivation."},{"q":"Pathetic fallacy is…","o":["weather or setting that reflects characters' feelings or mood","a sad character","a pathetic hero","a logical mistake"],"l":2,"e":"E.g. a storm during a violent scene."},{"q":"A symbol is…","o":["an object, colour or event that represents a wider idea","a chapter title","a narrator","a quotation"],"l":2,"e":"E.g. a locked door representing secrecy."},{"q":"Which features does the prose fiction rubric suggest?","o":["Characterisation, setting, language, key incident(s), climax, turning point, plot, structure, narrative technique, theme, ideas, description","Rhyme scheme, metre","Camera angle, mise-en-scène","Statistics"],"l":2,"e":"From the specimen paper's Part B introduction."},{"q":"Which features does the prose non-fiction rubric suggest?","o":["Ideas, use of evidence, stance, style, selection of material, narrative voice","Rhyme, stanza","Stage directions","Lighting and sound"],"l":2,"e":"Prose non-fiction includes memoir, travel writing, journalism and essays."},{"q":"Which counts as prose non-fiction?","o":["A memoir or travel book","A short story","A novel","A screenplay"],"l":2,"e":"Non-fiction: autobiography, biography, journalism, essays, travel writing."},{"q":"\"Setting in time and place\" questions want you to…","o":["explain the setting and show how it shapes characters, mood and themes","describe the weather only","list place names","write about the author's home"],"l":2,"e":"Link the setting to the text as a whole."},{"q":"A turning point in a novel is…","o":["a moment after which events or a character change direction significantly","the last page","the first chapter","a description of setting"],"l":3,"e":"Explain what changes and why it matters."},{"q":"Characterisation can be created through…","o":["what a character says, does and thinks, how others react, and description","the cover of the book","the number of chapters","the font"],"l":2,"e":"Analyse methods, not just personality."}]},
"ce_poetry":{"name":"Poetry Essays & Terminology","area":"ce","questions":[{"q":"A stanza is…","o":["a group of lines forming a unit in a poem","a single line","a rhyme","a type of poem"],"l":1,"e":"Stanza structure can signal shifts in time, mood or focus."},{"q":"Enjambment is…","o":["a sentence or phrase running over the end of a line into the next","a pause in the middle of a line","a rhyme at the end of a line","a repeated line"],"l":1,"e":"Enjambment can create momentum or place emphasis on the first word of the next line."},{"q":"A caesura is…","o":["a pause within a line, often marked by punctuation","the final line","a rhyme","a run-on line"],"l":2,"e":"A caesura slows the pace and emphasises what comes before/after."},{"q":"Rhythm in poetry is…","o":["the pattern of stressed and unstressed syllables / the beat of the lines","the number of stanzas","the poem's title","the rhyme scheme"],"l":2,"e":"Rhythm can mimic movement, emotion or speech."},{"q":"A volta is…","o":["a turn in thought or mood, e.g. in a sonnet","a type of stanza","a repeated sound","a rhyme scheme"],"l":2,"e":"Look for words like \"but\", \"yet\", \"now\"."},{"q":"Assonance is…","o":["repetition of vowel sounds","repetition of consonants at the start of words","a comparison","a contradiction"],"l":2,"e":"E.g. \"the low moan of the stone\"."},{"q":"Sibilance is…","o":["repetition of \"s\" sounds","repetition of vowel sounds","rhyme","onomatopoeia"],"l":2,"e":"It can suggest hissing, softness or menace."},{"q":"Which features does the poetry rubric suggest?","o":["Word choice, tone, imagery, structure, content, rhythm, rhyme, theme, sound, ideas","Camera work, editing","Stage directions","Statistics, evidence"],"l":2,"e":"Typical poetry rubric features."},{"q":"A dramatic monologue is…","o":["a poem spoken by a character (not the poet) revealing their personality and situation","a poem with no speaker","a play","a ballad"],"l":2,"e":"E.g. Duffy's \"Havisham\" or \"Mrs Midas\"."},{"q":"The \"persona\" of a poem is…","o":["the voice/speaker created by the poet","the poet's biography","the reader","the title"],"l":2,"e":"Distinguish the speaker from the poet."},{"q":"An oxymoron is…","o":["two contradictory terms placed together","a repeated word","a comparison using \"like\"","a question"],"l":2,"e":"E.g. \"Beloved sweetheart bastard\" (Duffy, \"Havisham\") clashes love and hatred."},{"q":"A sonnet traditionally has…","o":["14 lines","12 lines","16 lines","10 lines"],"l":2,"e":"Shakespearean and Petrarchan sonnets both have 14 lines."},{"q":"Why should a poetry essay discuss structure as well as word choice?","o":["Structure (stanza breaks, line endings, volta, final line) shapes meaning and emphasis","Structure is the only thing that matters","Markers ignore language","It makes the essay longer"],"l":3,"e":"Analysis of features of language includes structure and sound."},{"q":"\"Free verse\" means…","o":["poetry without a regular rhyme scheme or metre","poetry that costs nothing","a poem about freedom","a sonnet"],"l":2,"e":"Many modern poems use free verse."}]},
"ce_film":{"name":"Film & TV Drama Essays","area":"ce","questions":[{"q":"Mise-en-scène refers to…","o":["everything placed in the frame: setting, props, costume, lighting, actors' positioning","the soundtrack","the editing","the credits"],"l":1,"e":"It's a key filmic technique to analyse."},{"q":"A close-up shot…","o":["shows a face or object in detail, often to reveal emotion","shows a whole landscape","shows two characters talking","is filmed from above"],"l":1,"e":"Close-ups create intimacy or highlight significance."},{"q":"A low-angle shot (camera looking up at a character) usually makes the character seem…","o":["powerful or threatening","weak and vulnerable","distant","comic"],"l":2,"e":"High angles tend to diminish; low angles empower."},{"q":"Diegetic sound is…","o":["sound that exists within the world of the film (dialogue, a radio playing)","background music added in editing","the director's commentary","silence"],"l":2,"e":"Non-diegetic sound (e.g. score) is added for the audience only."},{"q":"Non-diegetic sound is…","o":["sound the characters cannot hear, such as a musical score or voice-over","footsteps in the scene","dialogue","a phone ringing on set"],"l":2,"e":"It shapes the audience's emotional response."},{"q":"A \"cut\" in editing is…","o":["an instant change from one shot to another","a scene removed from the film","a type of lighting","a camera angle"],"l":2,"e":"Pace of cutting affects tension."},{"q":"Cross-cutting (parallel editing) is…","o":["cutting between two scenes happening at the same time","slow-motion footage","an establishing shot","a fade to black"],"l":2,"e":"It builds tension or makes comparisons."},{"q":"An establishing shot…","o":["sets the scene, usually a wide/long shot of the location","is always a close-up","ends the film","shows credits"],"l":2,"e":"It orients the audience."},{"q":"Low-key lighting (strong shadows) often creates…","o":["mystery, menace or tension","a cheerful mood","a documentary feel","comedy"],"l":2,"e":"Common in thrillers, horror and film noir."},{"q":"Which features does the film & TV drama rubric suggest?","o":["Use of camera, key sequence, characterisation, mise-en-scène, editing, setting, music/sound, special effects, plot, dialogue","Rhyme, metre","Statistics, stance","Stanza, volta"],"l":2,"e":"The film rubric lists filmic techniques like these."},{"q":"What does the essay grid say about analysis for film?","o":["It rewards analysis of the effect of \"filmic techniques\"","Film essays don't need analysis","Only plot counts","Only dialogue counts"],"l":2,"e":"The grid refers to \"features of language/filmic techniques\"."},{"q":"A strong film paragraph about a key sequence would…","o":["describe specific shots, sound and editing at a precise moment and explain their effect on the audience and the film's themes","summarise the whole plot","discuss the actors' private lives","review the film's box office"],"l":3,"e":"Precise \"shot-by-shot\" reference is the equivalent of quotation."},{"q":"A tracking shot is…","o":["the camera moves alongside the action","the camera stays still","an extreme close-up","a flashback"],"l":2,"e":"Movement can involve the viewer or follow a character."}]},
"ce_language":{"name":"Language Study Essays","area":"ce","questions":[{"q":"What does the \"language\" genre in the critical essay cover?","o":["The study of language use, e.g. persuasive language, the language of a group or community, Scots language, spoken language","Only Shakespeare","Only poetry","Only foreign languages"],"l":1,"e":"You write about language features from your own studies."},{"q":"What do language essay questions ask you to refer to?","o":["\"Specific examples\" of language from your studies","Only one poem","Camera angles","The plot of a novel"],"l":2,"e":"The specification: language questions ask candidates to identify and refer to specific examples."},{"q":"What is \"dialect\"?","o":["A form of a language particular to a region or social group, with its own vocabulary and grammar","A foreign language","Slang only","Formal written English"],"l":2,"e":"E.g. Doric, Glaswegian Scots."},{"q":"What is \"accent\"?","o":["The way words are pronounced by a group or region","A type of grammar","A written style","A spelling mistake"],"l":2,"e":"Accent concerns pronunciation only; dialect includes vocabulary and grammar."},{"q":"What is \"jargon\"?","o":["Specialist vocabulary used by a particular profession or group","Rude language","Rhyming slang","Old-fashioned words"],"l":2,"e":"E.g. medical or gaming jargon — can include insiders and exclude outsiders."},{"q":"\"Emotive language\" in advertising or campaigns is used to…","o":["provoke strong feelings that persuade the audience","give neutral information","confuse readers","fill space"],"l":2,"e":"E.g. charity appeals."},{"q":"Which technique is common in persuasive language?","o":["Rhetorical questions, inclusive \"we\", repetition, rule of three, direct address","Footnotes","Passive voice only","Long technical lists"],"l":2,"e":"Persuasive features to analyse with examples."},{"q":"What is \"code-switching\"?","o":["Moving between languages, dialects or registers depending on context","A computing term only","Spelling words differently","Translating a text"],"l":2,"e":"Many Scots speakers switch between Scots and Standard English."},{"q":"What is \"sociolect\"?","o":["Language variety associated with a social group (e.g. age, class, occupation)","A regional accent","A written genre","Formal register"],"l":2,"e":"Sociolect relates to social groups; dialect usually to region."},{"q":"A strong language essay would…","o":["analyse specific, accurately recorded examples and evaluate their purpose and effect for a group/audience","describe a novel's plot","list words without comment","give only personal opinions"],"l":2,"e":"Analyse and evaluate specific examples."},{"q":"The \"rule of three\" (tricolon) is…","o":["grouping ideas in threes for memorability and emphasis","using three quotations","three paragraphs","three speakers"],"l":2,"e":"E.g. \"Education, education, education.\""},{"q":"Why might a political speech use the inclusive pronoun \"we\"?","o":["To create unity and a sense that speaker and audience share the same goals","To show grammar skill","To exclude the audience","To sound formal"],"l":3,"e":"Inclusive address builds solidarity."}]},
"st_skills":{"name":"Scottish Text Section — How It Works","area":"skills","questions":[{"q":"How many marks is Section 1 (Scottish text) of Critical Reading worth?","o":["20","10","30","25"],"l":1,"e":"Section 1 is 20 marks; Section 2 (critical essay) is another 20."},{"q":"From session 2026–27, how many marks is the final Scottish text question worth?","o":["8","10","6","12"],"l":2,"e":"Qualifications Scotland changed the final question from 10 to 8 marks from 2026–27."},{"q":"From 2026–27, how many marks are available for the questions on the printed extract or poem (before the final question)?","o":["12","10","8","16"],"l":2,"e":"The initial analysis questions now total 12 marks (up from 10); the final question is 8."},{"q":"How are the 8 marks in the final question split (from 2026–27)?","o":["2 commonality + 2 the extract + 4 elsewhere in the text/other texts","2 + 2 + 6","4 + 4","8 for elsewhere only"],"l":2,"e":"The change notice: 2 for commonality, 2 for the extract, and now 4 (not 6) for 'elsewhere' comments."},{"q":"What does \"commonality\" mean in the final question?","o":["Identifying what the extract and the rest of the text/other poems have in common in relation to the question","Listing common words","Writing about a different writer","Describing the plot"],"l":2,"e":"E.g. \"Duffy uses contrast (1) to explore growing up, loss and identity (1).\""},{"q":"Can the final Scottish text question be answered in bullet points?","o":["Yes — bullet points or a number of linked statements","No — it must be an essay","Only for poetry","Only for commonality"],"l":2,"e":"The marking instructions explicitly allow bullet points or linked statements."},{"q":"How many marks does a detailed/insightful comment plus quotation/reference earn in the final question's 'elsewhere' section?","o":["2","1","3","4"],"l":2,"e":"Award 2 for detailed/insightful comment plus quotation/reference, 1 for more basic comment plus reference, 0 for reference alone."},{"q":"For poetry, what does 'elsewhere' mean in the final question?","o":["At least one other poem by the same poet (or from the same collection)","Any poem by any poet","The same poem, a different stanza","A poem from your critical essay"],"l":2,"e":"E.g. \"By referring to this poem and to at least one other poem by Jamie…\"."},{"q":"For a play or novel, 'elsewhere' means…","o":["other parts of the same text","another play by the same writer","the film adaptation","your critical essay text"],"l":2,"e":"E.g. \"By referring to this extract and to elsewhere in the play…\"."},{"q":"In Section 1 how many texts do you answer on?","o":["One extract/poem — the text you have studied","Two extracts","All the extracts in your genre","Three poems"],"l":2,"e":"You choose the extract for the writer/text you studied and answer its questions."},{"q":"In the extract questions, a 4-mark question asking you to analyse \"by referring to at least two examples\" is usually marked…","o":["2+2, 2+1+1 or 1+1+1+1","4 for one example","1 per quotation","Holistically out of 4"],"l":3,"e":"That's the standard pattern in the Scottish text marking instructions."},{"q":"Which mistake do markers say costs most in the final question?","o":["Retelling or quoting without commenting on how it links to the question","Using bullet points","Writing in the present tense","Mentioning the writer's name"],"l":2,"e":"0 marks for quotation/reference alone — every reference needs a relevant comment."},{"q":"Why prepare 4–6 key quotations for each theme of your set text?","o":["So you can answer whatever final question appears with precise references from elsewhere","Because you must write them all down","Because quotations earn marks on their own","To fill time"],"l":2,"e":"Questions vary (theme, character, technique); flexible, well-chosen references are essential."},{"q":"A 2026–27 final question says \"discuss how Lochhead explores the theme of personal and/or social change\". A strong commonality statement would be…","o":["\"Lochhead uses characters to represent past and present (1), showing that change can destroy valuable aspects of the past or offer a more positive future (1).\"","\"Lochhead wrote many poems.\"","\"Change is when things are different.\"","\"In this poem the grandmother knits.\""],"l":3,"e":"Taken from the specimen marking instructions."}]},
"st_slab":{"name":"The Slab Boys — John Byrne","area":"drama","questions":[{"q":"Where is The Slab Boys set?","o":["The slab room of A.F. Stobo & Co., a carpet factory in Paisley","A shipyard in Glasgow","A school in Stornoway","A tenement in the East End"],"l":1,"e":"All the action takes place in the slab room, where boys grind and mix colours for the designers."},{"q":"When is The Slab Boys set?","o":["A Friday in 1957","The 1930s Depression","During the First World War","2020"],"l":1,"e":"The play takes place on one Friday (morning and afternoon) in 1957."},{"q":"Who wrote The Slab Boys?","o":["John Byrne","Ena Lamont Stewart","Donald S Murray","Iain Crichton Smith"],"l":1,"e":"John Byrne (1940–2023), from Paisley; the play is semi-autobiographical."},{"q":"What is Phil McCann's main ambition?","o":["To escape the slab room by getting into Glasgow School of Art","To become a designer at Stobo's","To marry Sadie","To join the army"],"l":2,"e":"Phil is talented; his Art School application is rejected — the marking instructions link this to class prejudice."},{"q":"Which character is the timid, put-upon slab boy who is unexpectedly promoted to a desk at the end?","o":["Hector","Spanky","Alan","Jack Hogg"],"l":2,"e":"The boys assume Hector has been sacked, but he gets a desk in the design room."},{"q":"Who is Alan Downie?","o":["A middle-class student working temporarily in the slab room, whose father is a chief designer elsewhere in the trade","The factory owner","The tea lady's son","A former slab boy now a designer"],"l":2,"e":"Alan represents privilege; the slab boys mock his clothes and possessions."},{"q":"Who is Willie Curry?","o":["The boss of the slab room/design department, authoritarian and nostalgic","Phil's father","The union rep","A sketcher"],"l":2,"e":"The marking instructions show him favouring Alan while dismissing the slab boys."},{"q":"Which female character is a sketcher whom several boys want to take to the staff dance?","o":["Lucille Bentley","Sadie","Isa","Jenny"],"l":2,"e":"Lucille is determined to decide her own destiny rather than settle like Sadie."},{"q":"Sadie, the tea lady, is used to explore…","o":["the lack of opportunities for women and an unhappy, loveless marriage","the glamour of 1950s youth","artistic talent","army life"],"l":2,"e":"Marking instructions: Sadie's desire to escape her loveless marriage shows women's limited control over their lives."},{"q":"How does Phil react to losing his job at the end?","o":["He refuses to be downcast and cartwheels off stage","He begs Curry to keep him","He fights Spanky","He leaves for America"],"l":2,"e":"The specimen marking instructions cite this as showing the power of youth."},{"q":"Which themes are central to The Slab Boys?","o":["Class, frustrated ambition, authority and rebellion, gender and youth","War and remembrance","Climate change","Religion and the supernatural"],"l":2,"e":"These recur throughout the official marking guidance."},{"q":"Which genre features does the play blend?","o":["Comedy (quick-fire wit, slapstick) with serious social criticism","Tragedy and myth","Science fiction","Verse drama"],"l":2,"e":"Humour masks frustration and class anger."},{"q":"Spanky's position at the end of the play is used to show…","o":["ordinary people ground down by the establishment, stuck in a soul-destroying job","his success in America","his promotion","his love for Lucille"],"l":3,"e":"From the specimen marking instructions."},{"q":"Why is the single setting of the slab room significant?","o":["It creates a sense of confinement that reflects the boys' limited prospects","It is cheap to stage","It shows the glamour of art","It allows time to pass quickly"],"l":3,"e":"The unchanging, cluttered room mirrors their trapped lives."},{"q":"FINAL QUESTION PRACTICE (8 marks)\n\nBy referring to an extract you have studied and to elsewhere in the play, discuss how Byrne uses conflict to explore central concerns.\n\n(Mark yourself: 2 commonality, 2 the extract, 4 elsewhere.)","m":8,"p":["Commonality: Byrne uses conflict between/within characters (1) to explore concerns such as class, rebellion against authority and gender (1)","Extract: a detailed comment on conflict in the given scene linked to a central concern (2)","Curry sees the slab boys as layabouts and disrespectful of authority — conflict highlights generational/authority tensions","The slab boys mock Alan's attire and possessions because he represents the privileged middle class","Alan taking Lucille to the dance creates conflict with Phil and Spanky, seen as part of class injustice","Phil's rejection by the Art School leads to frustration and confrontation with Curry, highlighting class inequality","Phil and Spanky clash when Phil suggests Spanky is siding with the bosses — differing attitudes to authority"],"l":3,"h":"Commonality first, then two or more developed references from elsewhere."}]},
"st_seq":{"name":"Sequamur — Donald S Murray","area":"drama","questions":[{"q":"What does the title \"Sequamur\" mean?","o":["\"Let us follow\" — the Latin motto of the Nicolson Institute","\"We remember\"","\"Fortune favours the brave\"","\"Peace at last\""],"l":1,"e":"The title is the school motto, ironic given how pupils followed Gibson's encouragement to war."},{"q":"Where is Sequamur set?","o":["The Nicolson Institute, a real school in Stornoway on the Isle of Lewis","A Paisley carpet factory","Edinburgh Castle","A Glasgow tenement"],"l":1,"e":"The play is set in a real school in Stornoway."},{"q":"Who is the central character?","o":["William J. Gibson, the school's headmaster (rector)","Duncan Finlayson","Mrs Finlayson","Donald"],"l":2,"e":"Gibson was a real man, headmaster of the Nicolson Institute from 1894 to 1925."},{"q":"What event frames the play's opening?","o":["Preparations to unveil a memorial plaque to former pupils killed in the First World War","A school prize-giving","The outbreak of the Second World War","A ship arriving"],"l":2,"e":"The play opens as the memorial is about to be unveiled; two names are missing."},{"q":"Around 148 former pupils of the school were killed in the war. What does Gibson come to feel about his role?","o":["Guilt for encouraging his pupils to enlist","Pride that his teaching worked","Indifference","Anger at the pupils"],"l":2,"e":"Official marking guidance: Gibson struggles with overwhelming guilt for encouraging his pupils to sign up."},{"q":"Gibson's early enthusiasm for war is shaped mainly by…","o":["his knowledge of classical literature (e.g. Homer)","his own experience as a soldier","newspapers from America","his wife's opinion"],"l":2,"e":"The 2026 marking instructions note he reverts to the classics to support the belief that war would be enriching."},{"q":"Mrs Finlayson represents…","o":["parents whose lives were shattered by losing sons in the war","the government","the school board","soldiers who returned unharmed"],"l":2,"e":"She searches for her son's name on the plaque."},{"q":"How is Jessie affected by the war?","o":["She is physically harmed by Donald, who suffers trauma (PTSD) from the war","She becomes a nurse","She leaves Lewis","She joins the army"],"l":2,"e":"Marking guidance cites this to show the war's impact long after it ended."},{"q":"How does the play move through time?","o":["Flashbacks to before and during the war, with dead pupils appearing as memories or ghosts","Strictly in chronological order","It is set entirely in the trenches","It jumps forward to the present day"],"l":2,"e":"Characters appear as memories or ghosts haunting Gibson."},{"q":"Paterson, a pupil, questions the war because…","o":["his father fought in the Boer War and told him how those in power send others to fight","he is a pacifist preacher","he fears the sea","he wants to be a teacher"],"l":2,"e":"From the 2026 marking instructions."},{"q":"Which themes are central to Sequamur?","o":["War and its impact, remembrance, guilt, deception, the influence of those in authority","Class in a carpet factory","Climate change","The supernatural and kelpies"],"l":2,"e":"War, remembrance and history are at the heart of the play."},{"q":"Why is the motto \"Sequamur\" ironic?","o":["The young men \"followed\" Gibson's lead to their deaths; at the end he asks those left to follow them in remembrance","Because the school had no motto","Because it is in Gaelic","Because nobody followed anyone"],"l":3,"e":"The motto's meaning shifts across the play."},{"q":"How do the soldiers' letters (e.g. Morrison's) affect Gibson?","o":["They confront him with the brutal reality of war — mud, cold, death — which he had not understood","They reassure him the war is glorious","They are never read","They make him angry at the soldiers"],"l":3,"e":"The specimen extract uses Morrison's letter to expose the reality."},{"q":"FINAL QUESTION PRACTICE (8 marks)\n\nBy referring to an extract you have studied and to elsewhere in the play, discuss how Murray explores the impact of war.\n\n(2 commonality, 2 extract, 4 elsewhere.)","m":8,"p":["Commonality: at first war is presented as glorious and honourable (1); as the play progresses its reality — guilt, suffering, injustice, deception — is revealed (1)","Extract: a detailed comment on how the chosen scene shows war's impact (2)","The huge number of former pupils on the plaque shows the far-reaching impact on communities and generations","Mrs Finlayson searching for her son's name represents parents' life-long suffering","The fate of very young men sent to war as 'cannon fodder' highlights injustice/the ineptitude of officers","Gibson is tormented by guilt once he learns the horrors his former pupils faced","Jessie is harmed by Donald, traumatised by war — impact on families long after it ended"],"l":3,"h":"Show the shift from glory to reality."}]},
"st_msw":{"name":"Men Should Weep — Ena Lamont Stewart","area":"drama","questions":[{"q":"Where and when is Men Should Weep set?","o":["A tenement in the East End of Glasgow during the 1930s Depression","A Paisley factory in 1957","Stornoway after WW1","Edinburgh in the 1880s"],"l":1,"e":"Poverty and overcrowding in a Glasgow tenement are central."},{"q":"Who is the central character?","o":["Maggie Morrison","Lily","Isa","Granny"],"l":1,"e":"Maggie holds the family together practically and emotionally."},{"q":"What is John Morrison's situation at the start of the play?","o":["He is unemployed and refuses to help with work in the home","He is a successful shipyard foreman","He is away at war","He is in hospital"],"l":2,"e":"His unemployment and pride put great strain on Maggie."},{"q":"Who is Lily?","o":["Maggie's sister, who works in a pub and is cynical about men and marriage","Maggie's daughter","John's mother","A neighbour's child"],"l":2,"e":"Lily criticises John and Maggie's 'slavin efter a useless man'."},{"q":"Which child is seriously ill and has to go to hospital?","o":["Bertie","Alec","Edie","Jenny"],"l":2,"e":"Bertie's illness (tuberculosis) shows the effect of poverty and poor housing on health."},{"q":"Jenny, the eldest daughter, …","o":["leaves home after conflict and later returns with money","becomes a nurse","marries Alec","dies of TB"],"l":2,"e":"Jenny's leaving pushes Maggie to breaking point; her return changes the ending."},{"q":"How is Granny treated?","o":["She is passed between relatives as she has no home of her own","She owns the flat","She runs the family","She lives in a care home"],"l":2,"e":"This shows poverty and the plight of the elderly."},{"q":"Alec, Maggie's son, is married to…","o":["Isa, who is flirtatious, selfish and contemptuous of him","Lily","Jenny","Mrs Bone"],"l":2,"e":"Their marriage shows destructive relationships and domestic conflict."},{"q":"What is the significance of the play's title?","o":["It echoes the saying that \"men must work and women must weep\", reversing it to criticise men's treatment of women","It refers to a war memorial","It is a line from Burns","It names a pub"],"l":2,"e":"The title challenges gender roles."},{"q":"Which themes are central?","o":["Poverty, gender roles and the oppression of women, family, class, domestic conflict","War and guilt","Supernatural forces","Climate change"],"l":2,"e":"These appear throughout the official marking guidance."},{"q":"How does Maggie change by the end of the play?","o":["She takes control of her life, defying John to do what is best for her family","She leaves for America","She becomes more submissive","She dies"],"l":3,"e":"Marking guidance: Maggie takes control, exploring the strength of the individual."},{"q":"The neighbours (e.g. Mrs Harris, Mrs Bone, Mrs Wilson) mainly show…","o":["the community support poor families depend on — and their gossip","wealthy middle-class life","the factory bosses","the church"],"l":2,"e":"Maggie says she depends on neighbours because of poverty."},{"q":"Which feature of the language helps create realism?","o":["Glasgow dialect/Scots in the dialogue, e.g. 'midden', 'naethin'","Verse and rhyme","Formal legal language","Latin mottoes"],"l":2,"e":"Dialect anchors the play in its working-class setting."},{"q":"FINAL QUESTION PRACTICE (8 marks)\n\nBy referring to an extract you have studied and to elsewhere in the play, discuss how Lamont Stewart uses the character of Maggie to explore central concerns.\n\n(2 commonality, 2 extract, 4 elsewhere.)","m":8,"p":["Commonality: Maggie, the wife and mother who holds the family together practically and emotionally (1), explores themes such as the role of women, poverty and family (1)","Extract: a detailed comment linking Maggie's words/actions in the scene to a central concern (2)","Opening scenes: down-trodden, exhausted, running a chaotic home, loyal to John — oppression of women","Her constant battle to feed the family (e.g. the tin of beans) — poverty","Reaching breaking point (Jenny leaving, Bertie's illness) — family pressure","Affectionate but irritated treatment of Granny, put to bed early in the overcrowded house — vulnerability of the old","Taking control of her life at the end — strength of the individual"],"l":3,"h":"Link each reference to a named concern."}]},
"st_jekyll":{"name":"Dr Jekyll and Mr Hyde — R L Stevenson","area":"prose","questions":[{"q":"Who wrote The Strange Case of Dr Jekyll and Mr Hyde (1886)?","o":["Robert Louis Stevenson","Walter Scott","Iain Crichton Smith","Arthur Conan Doyle"],"l":1,"e":"Stevenson (1850–1894) was born in Edinburgh; the novella is set in Victorian London."},{"q":"Who is the main narrating/viewpoint character for most of the novella?","o":["Mr Utterson, a lawyer","Dr Lanyon","Poole","Mr Enfield"],"l":1,"e":"Much of the story follows Utterson's investigation."},{"q":"In \"Story of the Door\", what does Enfield describe Hyde doing?","o":["Trampling a young girl in the street","Murdering Carew","Robbing a bank","Breaking into Jekyll's house"],"l":2,"e":"Enfield's account introduces Hyde's callous violence; Hyde pays compensation with a cheque signed by Jekyll."},{"q":"Who is murdered by Hyde?","o":["Sir Danvers Carew, an MP","Mr Utterson","Dr Lanyon","Poole"],"l":2,"e":"Hyde beats Carew to death; the specimen guidance contrasts Carew's courtesy with Hyde's bestial violence."},{"q":"What causes Dr Lanyon's illness and death?","o":["The shock of seeing Hyde transform into Jekyll","A fall in the street","Hyde attacks him","Poisoning"],"l":2,"e":"The 2026 marking instructions: the secret is so shocking it causes Lanyon's illness and death."},{"q":"Why is Jekyll's will a source of worry for Utterson?","o":["It leaves everything to Edward Hyde","It leaves nothing to anyone","It names Utterson as a suspect","It is missing"],"l":2,"e":"The will makes Utterson suspect Hyde has a hold over Jekyll."},{"q":"What does the contrast between the front of Jekyll's house and the laboratory door represent?","o":["The respectable public face (Jekyll) versus the hidden, shabby side (Hyde)","Wealth versus poverty in London","Old versus new architecture","Science versus religion"],"l":2,"e":"From the specimen marking instructions."},{"q":"Which key idea does Jekyll state in his \"Full Statement\"?","o":["That \"man is not truly one, but truly two\"","That science will save humanity","That Hyde was his brother","That he never took the potion"],"l":2,"e":"Duality of human nature is the novella's central concern."},{"q":"Which themes dominate the novella?","o":["Duality, secrecy and reputation, good and evil, Victorian respectability and hypocrisy","Class in a carpet factory","War and remembrance","Climate change"],"l":2,"e":"Secrecy is shown destroying friendship and morality."},{"q":"How does the novella end?","o":["Utterson and Poole break into the cabinet and find Hyde dead; the truth is revealed in Lanyon's narrative and Jekyll's statement","Hyde escapes to France","Jekyll is arrested","Utterson becomes Hyde"],"l":2,"e":"The final chapters are documents that explain the mystery."},{"q":"How is Hyde often described?","o":["In animal-like terms, e.g. \"ape-like\" fury, and as somehow deformed","As handsome and charming","As tall and noble","As a kindly old man"],"l":2,"e":"Animal imagery stresses his primitive evil."},{"q":"Why does the story use multiple narratives and documents?","o":["To build mystery — the reader, like Utterson, pieces together the truth, with the full explanation withheld until the end","To confuse the reader deliberately for no reason","Because Stevenson ran out of time","To show different countries"],"l":3,"e":"The structure delays revelation and creates suspense."},{"q":"What does the specimen guidance say Jekyll's cabinet scene (tea table set, fire burning, Hyde's twitching body) reveals?","o":["The darkness at the heart of respectable Victorian society","That Jekyll was poor","That Poole was guilty","That Hyde was innocent"],"l":3,"e":"The contrast of homely respectability with horror."},{"q":"FINAL QUESTION PRACTICE (8 marks)\n\nBy referring to an extract you have studied and to elsewhere in the novel, discuss how Stevenson explores the impact of secrecy.\n\n(2 commonality, 2 extract, 4 elsewhere.)","m":8,"p":["Commonality: secrecy has a negative impact on characters, atmosphere and events (1), leading to hypocrisy, destruction of friendship and moral decline (1)","Extract: a detailed comment on secrecy in the chosen passage (e.g. Jekyll refusing to discuss the will) (2)","The need for secrecy about his 'guilty pleasures' to stay respectable leads Jekyll to create Hyde","The secret division of Jekyll's nature drives the two sides apart and Hyde's behaviour becomes more monstrous","Jekyll's inability to share his suffering isolates him — e.g. shutting himself in his cabinet","The revealed secret causes Lanyon's illness and death","Utterson's decision to keep the dual identity secret shows secrecy's corrupting effect even on a respectable lawyer"],"l":3,"h":"Show secrecy's effects on characters and events."}]},
"st_sunlight":{"name":"The Sunlight Pilgrims — Jenni Fagan","area":"prose","questions":[{"q":"Where is The Sunlight Pilgrims mainly set?","o":["A caravan park at Clachan Fells, a fictional place in the north of Scotland","A Glasgow tenement","Victorian London","Stornoway"],"l":1,"e":"Most of the action is in the caravan park at Clachan Fells."},{"q":"What is happening to the climate in the novel?","o":["The world is freezing — a possible new ice age, with temperatures plunging","A heatwave and drought","Constant rain and floods only","Nothing unusual"],"l":1,"e":"The novel is set over the winter of an imagined 2020–21 as temperatures drop."},{"q":"Why does Dylan leave London?","o":["After losing his mother, his grandmother and the family's art-house cinema, he travels north to a caravan his mother bought","He is sent by his job","He is a soldier","He wants to climb mountains"],"l":2,"e":"He brings their ashes with him."},{"q":"Who is Stella?","o":["A twelve-year-old trans girl who lives with her mother Constance","Dylan's sister","A teacher","Constance's mother"],"l":2,"e":"Stella faces bullying at school and her father's refusal to accept her transition."},{"q":"How does Constance make a living?","o":["Upcycling and selling furniture scavenged from the dump","Running the caravan park","Teaching at the school","Fishing"],"l":2,"e":"The specimen marking instructions highlight her adaptability."},{"q":"Stella's father, Alistair, …","o":["refuses to accept her transition and continues to call her Cael","lives with them","is a doctor","supports her fully"],"l":2,"e":"The 2026 marking instructions note their strained relationship."},{"q":"How does the climate crisis affect the three main characters?","o":["It draws them together like a family as they support each other","It drives them apart forever","It has no effect","It makes Dylan return to London"],"l":2,"e":"E.g. Constance makes a woodstove for Dylan's caravan."},{"q":"Which themes are central?","o":["Identity and acceptance, resilience, family and community, the impact of change, the climate crisis","War and guilt","Class in a 1950s factory","The supernatural"],"l":2,"e":"All appear in official marking guidance."},{"q":"How is Constance presented?","o":["As tough, independent and unconventional, unconditionally supporting Stella","As cruel to Stella","As helpless","As a minor character"],"l":2,"e":"She speaks up about derogatory notes about Stella at the community meeting."},{"q":"What does the specimen guidance say Dylan's journey north shows?","o":["Inner strength — after losing his family and home he travels alone to an unknown part of Scotland","His wealth","His wish to escape the law","His love of cold weather"],"l":3,"e":"Challenging situations bring out hidden strengths."},{"q":"The novel was published in 2016 but set in 2020–21. Its vision of the future is…","o":["speculative — a near-future warning about climate disaster","historical","a documentary record","set in the distant past"],"l":2,"e":"The situation depicted was imagined."},{"q":"In the 2026 extract, details like news-stands \"covered in headlines\" and naval ships in the Thames suggest…","o":["a major global crisis unfolding while some people carry on as normal","a celebration","a calm ordinary day","a war in Scotland"],"l":3,"e":"The marking instructions note the contrast of crisis and normality."},{"q":"FINAL QUESTION PRACTICE (8 marks)\n\nBy referring to an extract you have studied and to elsewhere in the novel, discuss how Fagan explores the impact of change.\n\n(2 commonality, 2 extract, 4 elsewhere.)","m":8,"p":["Commonality: the main characters must adapt to the imminent danger facing society (1), showing how challenging situations change people — bringing out hidden strengths and bringing them together (1)","Extract: a detailed comment on how change affects a character in the chosen passage (2)","The climate background brings the eclectic caravan-park residents together — strength of human connection","Dylan makes a new life for himself in extreme circumstances","Stella, changing gender, stays strong despite criticism and judgement at school","Alistair refuses to accept change (calling Stella Cael), straining their relationship","Constance copes with extreme change, remaining reliable and accepting her daughter's identity"],"l":3,"h":"Personal change and climate change."}]},
"st_ics":{"name":"Short Stories — Iain Crichton Smith","area":"prose","questions":[{"q":"Which four Iain Crichton Smith stories are set for Higher?","o":["The Red Door, Mother and Son, The Painter, The Existence of the Hermit","The Telegram, The Painter, Home, The Red Door","Andrina, Death in a Nut, The Red Door, The Painter","Mother and Son, Duck Feet, Loast, The Painter"],"l":1,"e":"The set list names these four stories."},{"q":"Where did Iain Crichton Smith grow up, the setting that shapes many of his stories?","o":["The Isle of Lewis in the Western Isles","Paisley","Orkney","London"],"l":1,"e":"He wrote in English and Gaelic; island communities are central to his fiction."},{"q":"What happens at the start of The Red Door?","o":["Murdo wakes to find his door has been painted red overnight","Murdo's mother dies","A painter arrives in the village","A hermit moves in"],"l":2,"e":"The red door makes Murdo reflect on his conformist life."},{"q":"What does the red door symbolise?","o":["Individuality and a break from the conformity of village life","Danger and death","The church","Love for a neighbour"],"l":2,"e":"It prompts Murdo to question the restrictions of his community."},{"q":"In Mother and Son, John is…","o":["trapped caring for his bedridden, critical mother","a successful businessman","a fisherman lost at sea","a painter"],"l":2,"e":"Marking guidance: duty keeps him trapped, denying his true self."},{"q":"In The Painter, what does the young painter paint that turns the village against him?","o":["A violent fight between two villagers with scythes — and the onlookers' reactions","The church","A portrait of the narrator","The harbour at dawn"],"l":2,"e":"His painting shows the villagers' animal-like excitement, which they cannot accept."},{"q":"In The Painter, why does the community reject the boy?","o":["He forces them to see a savage side of themselves they don't want to acknowledge","He steals from them","He refuses to work","He is from England"],"l":2,"e":"Specimen guidance: he is ostracised rather than conforming."},{"q":"In The Existence of the Hermit, why is the hermit both an affront and a temptation?","o":["His refusal to conform to social norms challenges the community","He is wealthy","He is a criminal","He preaches at them"],"l":2,"e":"From the specimen marking instructions."},{"q":"A common central concern across the four stories is…","o":["the conflict between individuality and conformity in a close community","war and remembrance","climate change","life in London"],"l":2,"e":"The specimen final question asks exactly this."},{"q":"Crichton Smith often uses a narrator who is part of the community (e.g. in The Painter). The effect is…","o":["the reader sees the community's judgements from inside, exposing its narrowness and cruelty","the stories become science fiction","the narrator is always the hero","it removes any tension"],"l":3,"e":"Point of view reveals the community's attitudes."},{"q":"How does the narrator react inwardly while watching the painter in the 2026 extract?","o":["With rage and bitter disgust, mixed with some admiration","With calm approval","With boredom","With laughter"],"l":2,"e":"The 2026 marking instructions cite 'seethed through me' and 'most bitter disgust'."},{"q":"FINAL QUESTION PRACTICE (8 marks)\n\nBy referring to one story you have studied and to at least one other story, discuss how Crichton Smith explores the conflict between individuality and conformity.\n\n(2 commonality, 2 extract, 4 elsewhere.)","m":8,"p":["Commonality: characters who are different (artists, hermits, a man with a red door) clash with a narrow, judgemental community (1), exploring the cost of conformity and the value of self-expression (1)","Extract story: a detailed, relevant comment (2)","The Painter: villagers feel uncomfortable with the boy's individual view of the village, preferring their self-satisfied view","The Painter: the boy is ostracised for painting their animalistic reaction to the fight","Mother and Son: John feels trapped by his critical mother but duty keeps him there, denying his true self","The Red Door: Murdo's door prompts him to reflect on the pressures of living within the restrictions of a small community","The Existence of the Hermit: the hermit's disregard for social norms is an affront and a temptation to the villagers"],"l":3,"h":"Use at least two other stories for safety."}]},
"st_ssc":{"name":"Scottish Short Story Collection","area":"prose","questions":[{"q":"Which stories make up the Scottish short story collection (crossover N5/Higher)?","o":["A Voice Spoke to Me at Night, Things My Wife and I Found Hidden in Our House, Andrina, Death in a Nut","The Red Door, Mother and Son, The Painter, Andrina","Duck Feet, Loast, Andrina, The Painter","Death in a Nut, Hieroglyphics, Andrina, The Hermit"],"l":1,"e":"The set list names these four stories by four writers."},{"q":"Who wrote \"Andrina\"?","o":["George Mackay Brown","Kirsty Logan","Helen McClory","Duncan Williamson"],"l":1,"e":"Mackay Brown (1921–1996) wrote about his native Orkney."},{"q":"\"Death in a Nut\" is a traditional tale as told by…","o":["Duncan Williamson","Iain Crichton Smith","Robert Burns","Jenni Fagan"],"l":1,"e":"Williamson was a celebrated Scottish traveller storyteller; Scots dialogue is a key feature."},{"q":"In Death in a Nut, what does Jack do when Death comes for his mother?","o":["Beats Death, traps him inside a hazelnut shell and throws it away","Runs away","Offers his own life","Calls the doctor"],"l":2,"e":"Jack's fear of losing his mother drives his extreme action."},{"q":"What happens when Death is trapped?","o":["Nothing can die — so nothing can be killed for food and the natural cycle breaks down","Everyone becomes rich","The mother recovers fully at once","The village floods"],"l":2,"e":"The 2026 extract has the mother say \"Bithout Death there is no life\"."},{"q":"Which central concern does Death in a Nut explore?","o":["Death as a necessary part of the natural cycle of life, and the fear of losing a loved one","Climate change","Class in a factory","The power of the media"],"l":2,"e":"From the specimen marking instructions."},{"q":"In Andrina, what does the old man come to realise about Andrina?","o":["She was a ghost — not a living visitor at all","She was his neighbour's daughter","She had moved to the mainland","She was a thief"],"l":2,"e":"Marking guidance: she \"was never really there as a living being\"."},{"q":"In Andrina, what wrong did the old man commit in his youth?","o":["He abandoned Sigrid when she became pregnant","He stole a boat","He burned a croft","He lied in court"],"l":2,"e":"Sigrid's loyalty contrasts with his selfishness."},{"q":"Which supernatural being lies behind the strange items in \"Things My Wife and I Found Hidden in Our House\"?","o":["A kelpie","A ghost","A witch","A fairy queen"],"l":2,"e":"The couple gradually realise the 'gifts' are linked to a kelpie."},{"q":"In \"A Voice Spoke to Me at Night\", the modern narrator hears…","o":["an ancient man speaking in an archaic language of plague and hunger","a radio broadcast","their mother","a kelpie"],"l":2,"e":"The contrast highlights shared human suffering and loneliness across time."},{"q":"A central concern shared across the collection is…","o":["the power of the supernatural/unknown and human needs such as love, connection and the fear of loss","life in Victorian London","war","sport"],"l":2,"e":"Several stories blend the everyday and the uncanny."},{"q":"In Andrina, what does the contrast between the old man's loneliness without Andrina and the warmth when she visits highlight?","o":["The human need for closeness and the pain of isolation","That he prefers being alone","That Andrina is cruel","That Orkney is cold"],"l":3,"e":"From the 2026 marking instructions."},{"q":"FINAL QUESTION PRACTICE (8 marks)\n\nBy referring to one story you have studied and to at least one other story from the collection, discuss how the writers use contrast to explore central concerns.\n\n(2 commonality, 2 extract, 4 elsewhere.)","m":8,"p":["Commonality: contrast in characters, settings, situations or events (1) highlights aspects of human experience such as isolation, loss, betrayal, life and death (1)","Extract story: a detailed comment on a contrast in your chosen story (2)","Death in a Nut: Jack first sees Death as destructive, later understands it is needed to keep the world going","Andrina: Bill's loneliness when Andrina is gone versus warmth when she is present — isolation","Andrina: Bill abandoning pregnant Sigrid versus her loyalty — selfishness in relationships","A Voice Spoke to Me at Night: modern office/flat life versus the ancient man's plague and hunger — common humanity and loneliness","Things My Wife and I Found: calm after disposing of the 'gifts' versus the shock of hair round the doorknob — power of the supernatural"],"l":3,"h":"Contrast in character, setting, situation."}]},
"st_duffy":{"name":"Carol Ann Duffy","area":"poetry","questions":[{"q":"Which six Duffy poems are set for Higher?","o":["Originally, Mrs Midas, In Mrs Tilscher's Class, Medusa, Havisham, Before You Were Mine","Originally, Valentine, Prayer, War Photographer, Havisham, Medusa","Mrs Midas, Anne Hathaway, Originally, Little Red Cap, Medusa, Mean Time","Havisham, Stealing, Education for Leisure, Originally, Mrs Midas, Medusa"],"l":1,"e":"These six are on the Higher (crossover) list."},{"q":"\"Originally\" reflects Duffy's experience of…","o":["moving from Scotland to England as a child","moving to America","leaving school","becoming Poet Laureate"],"l":1,"e":"The poem explores emigration, belonging and identity."},{"q":"In \"Originally\", what does the speaker do to fit in at her new school?","o":["Loses her old accent and begins to sound like the other children","Joins a gang","Changes her name","Refuses to speak"],"l":2,"e":"Specimen guidance: losing her way of speaking — and sense of self — to be accepted."},{"q":"\"Mrs Midas\" is narrated by…","o":["the wife of King Midas, whose touch turns everything to gold","Midas himself","a servant","the god Dionysus"],"l":2,"e":"A dramatic monologue retelling the myth from the wife's view."},{"q":"What does Mrs Midas miss most, according to the specimen guidance?","o":["Her husband's touch / their intimacy — she realises they can never have a child","His money","Their house","Her job"],"l":2,"e":"His selfish wish destroys their relationship."},{"q":"\"Havisham\" is spoken by…","o":["the jilted bride from Dickens's Great Expectations","a Greek monster","a schoolteacher","a mother"],"l":2,"e":"Havisham is consumed by hatred after being abandoned."},{"q":"The opening \"Beloved sweetheart bastard\" in \"Havisham\" is an example of…","o":["oxymoron — love and hatred clashing","onomatopoeia","a simile","understatement"],"l":2,"e":"Specimen guidance: love versus hostility shows the destructive power of betrayal."},{"q":"In \"Medusa\", what turns the speaker's hair into snakes?","o":["Suspicion, doubt and jealousy","A curse from a god","Age","Grief for her mother"],"l":2,"e":"2026 marking instructions: 'a suspicion, a doubt, a jealousy' grew in her mind."},{"q":"\"In Mrs Tilscher's Class\" explores…","o":["the move from childhood innocence to the confusion of adolescence","life in a factory","a wedding","war"],"l":2,"e":"The classroom's wonders give way to disturbing new knowledge."},{"q":"\"Before You Were Mine\" is addressed to…","o":["the speaker's mother, imagining her glamorous life before the speaker was born","a lover","a teacher","a husband"],"l":2,"e":"The speaker admires her mother's youthful freedom."},{"q":"Which central concerns recur across the Duffy poems?","o":["Identity, growing up, love, betrayal, loss and change","War and remembrance","Climate change","Class in a factory"],"l":2,"e":"All appear in the official guidance."},{"q":"Duffy often uses the dramatic monologue. Its effect is…","o":["to give a voice to a persona (often a woman from myth or literature), revealing her feelings directly","to describe landscapes neutrally","to tell a story in the third person","to rhyme every line"],"l":3,"e":"Mrs Midas, Havisham and Medusa are all dramatic monologues."},{"q":"In \"Medusa\", the repeated \"Be terrified.\" suggests…","o":["she wants to cause harm — her pain has hardened into a desire to hurt","she is afraid herself","she is joking","she is reassuring her lover"],"l":3,"e":"From the 2026 marking instructions."},{"q":"FINAL QUESTION PRACTICE (8 marks)\n\nBy referring to one Duffy poem you have studied and to at least one other poem by Duffy, discuss how the poet uses contrast to explore central concerns.\n\n(2 commonality, 2 extract, 4 elsewhere.)","m":8,"p":["Commonality: Duffy uses contrast — e.g. childhood and adolescence, intimacy and distance, security and alienation (1) — to explore growing up, loss and identity (1)","Chosen poem: a detailed comment on a contrast and the concern it explores (2)","Before You Were Mine: the excitement of the dancehall versus her angry mother at home — the glorious adventure of youth","Mrs Midas: earlier intimacy versus distance after the wish — her longing for his touch","In Mrs Tilscher's Class: innocent enjoyment of the classroom versus the disturbing experience of adolescence","Havisham: love ('Beloved sweetheart') versus hatred ('bastard') — the destructive power of betrayal","Medusa: her past beauty versus her horrifying appearance now ('Look at me now') — insecurity and suspicion destroy happiness"],"l":3,"h":"Contrasts: childhood/adolescence, intimacy/distance, security/alienation."}]},
"st_maccaig":{"name":"Norman MacCaig","area":"poetry","questions":[{"q":"Which six MacCaig poems are set?","o":["Aunt Julia, Hotel Room 12th Floor, Basking Shark, On Lachie's Croft, Landscape and I, Old Highland Woman","Aunt Julia, Assisi, Visiting Hour, Memorial, Basking Shark, Sounds of the Day","Basking Shark, Toad, Frogs, Aunt Julia, Assisi, Memorial","Hotel Room, Visiting Hour, Assisi, Aunt Julia, Landscape and I, Toad"],"l":1,"e":"The current list (from 2025–26) is these six."},{"q":"In \"Aunt Julia\", why could the speaker not understand his aunt?","o":["She spoke Gaelic, which he did not understand","She was deaf","She whispered","She lived abroad"],"l":2,"e":"The poem regrets a lost heritage and the chance to know her."},{"q":"Aunt Julia represents…","o":["a lost Gaelic, crofting heritage that we should value and preserve","modern city life","violence in New York","the speaker's mother"],"l":2,"e":"Specimen guidance: she represents a lost heritage."},{"q":"In \"Basking Shark\", the speaker's encounter leads to which question?","o":["\"So who's the monster?\"","\"Where is the sea?\"","\"Why am I here?\"","\"What is the time?\""],"l":2,"e":"The poem challenges our sense of superiority over 'primitive' nature."},{"q":"\"Hotel Room, 12th Floor\" is set in…","o":["New York, where the speaker hears sounds of violence at night","Edinburgh","the Highlands","London"],"l":2,"e":"Darkness represents the savagery of humanity, however 'civilised'."},{"q":"In \"Landscape and I\", the mountain Schiehallion symbolises…","o":["the challenges humans face throughout life — \"The thing is, climb it.\"","wealth","death","tourism"],"l":2,"e":"2026 marking instructions quote \"There's a Shiehallion anywhere you go./The thing is, climb it.\""},{"q":"In \"On Lachie's Croft\", the bedraggled cockerel prompts the speaker to admit…","o":["\"I'm master of nothing I survey\" — his own lack of fulfilment","he loves farming","he is rich","he wants to cook it"],"l":2,"e":"The cockerel reflects the speaker's world-weariness."},{"q":"In \"Old Highland Woman\", \"Her people / are assembled in her bones\" suggests…","o":["she embodies generations of Highland heritage","she is very thin","she has many visitors","she is ill"],"l":2,"e":"From the specimen and 2026 marking instructions."},{"q":"Which central concerns recur in MacCaig's set poems?","o":["Heritage, identity, the natural world, the impact of time, human savagery","War and guilt","Climate change and ice ages","Factory work"],"l":2,"e":"All appear in official guidance."},{"q":"MacCaig often begins with a concrete observation and moves to a wider reflection. In \"Basking Shark\", this means…","o":["a real encounter with a shark leads to reflection on human evolution and destructiveness","he describes a fishing trip only","he tells a joke","he describes a meal"],"l":3,"e":"The specimen guidance: his reflections challenge our perception of superiority."},{"q":"In \"Old Highland Woman\", the old woman \"laughs a wicked cackle\" with \"love in it\". The effect is…","o":["to show her mischief and warmth — an almost oxymoronic mix","to make her a villain","to show she is sad","to show she is confused"],"l":2,"e":"The 2026 marking instructions note the link between 'wicked' and 'love'."},{"q":"FINAL QUESTION PRACTICE (8 marks)\n\nBy referring to one MacCaig poem you have studied and to at least one other poem by MacCaig, discuss how the poet uses symbolism and/or imagery to explore central concerns.\n\n(2 commonality, 2 extract, 4 elsewhere.)","m":8,"p":["Commonality: MacCaig uses symbolism/imagery of people, objects and places (1) to explore heritage, identity and the natural world (1)","Chosen poem: a detailed comment on a symbol/image (2)","Old Highland Woman: 'Her people / are assembled in her bones' — she represents generations of Highland heritage","Landscape and I: 'There's a Schiehallion anywhere you go' — the mountain symbolises life's challenges","Aunt Julia: she represents a lost heritage we should value and preserve","On Lachie's Croft: the 'bedraggled' cockerel represents the speaker's world-weariness","Hotel Room, 12th Floor: darkness represents the savage nature of humanity","Basking Shark: the shark represents 'primitive' nature, questioning human superiority"],"l":3,"h":"People, objects and places as symbols."}]},
"st_lochhead":{"name":"Liz Lochhead","area":"poetry","questions":[{"q":"Which six Lochhead poems are set?","o":["My Rival's House, Last Supper, Box Room, For My Grandmother Knitting, The Spaces Between, Sorting Through","Box Room, Revelation, The Bargain, View of Scotland, My Rival's House, Last Supper","Revelation, For My Grandmother Knitting, Box Room, The Choosing, Last Supper, Sorting Through","The Choosing, Box Room, My Rival's House, Revelation, The Spaces Between, Last Supper"],"l":1,"e":"The 2025–26 list includes two new poems: The Spaces Between and Sorting Through."},{"q":"\"Sorting Through\" is about…","o":["the speaker clearing out her late mother's clothes and remembering her","a teenager tidying a bedroom","sorting post at work","choosing a wedding dress"],"l":2,"e":"2026 marking instructions: grief and memory triggered by her mother's clothes."},{"q":"\"The Spaces Between\" explores…","o":["the effect of the lockdown separation on a grandmother and her grandchildren","a divorce","a city skyline","a train journey"],"l":2,"e":"Specimen guidance: lockdown's impact on each generation."},{"q":"In \"Box Room\", the speaker stays in…","o":["her boyfriend's childhood bedroom at his mother's house","a hotel","a prison cell","her grandmother's house"],"l":2,"e":"The room is a kind of shrine to the son; the mother will resist change."},{"q":"In \"My Rival's House\", who is the \"rival\"?","o":["The boyfriend's mother, who is possessive of her son","A former girlfriend","A sister","A teacher"],"l":2,"e":"The mother fights against her son growing up and forming a new relationship."},{"q":"\"Last Supper\" shows…","o":["a woman whose relationship has ended meeting female friends who 'pick over' the man — a dark side of female friendship","a religious ceremony","a family Christmas","a school dinner"],"l":2,"e":"Guidance: the women behave as predators at the table."},{"q":"\"For My Grandmother Knitting\" contrasts…","o":["the grandmother's past usefulness and skill with her present, when her family no longer needs her knitting","city and country life","two lovers","summer and winter only"],"l":2,"e":"Guidance: she represents an older Scotland of fishing/mining communities."},{"q":"Which central concerns recur across Lochhead's set poems?","o":["Relationships (family, romantic, friendship), change, grief, jealousy, loneliness and women's experience","War","Climate change","The supernatural"],"l":2,"e":"From the specimen and 2026 marking instructions."},{"q":"In \"Sorting Through\", \"binbags for Oxfam\" suggests…","o":["the speaker has to take a practical approach despite her grief","she is angry with her mother","she is careless","she is wealthy"],"l":3,"e":"The 2026 marking instructions."},{"q":"Lochhead was Scotland's national poet (Makar) from…","o":["2011 to 2016","1990 to 1995","2021 to 2024","2004 to 2010"],"l":2,"e":"Liz Lochhead served as Makar 2011–2016."},{"q":"FINAL QUESTION PRACTICE (8 marks)\n\nBy referring to one Lochhead poem you have studied and to at least one other poem by Lochhead, discuss how the poet uses relationships to explore central concerns.\n\n(2 commonality, 2 extract, 4 elsewhere.)","m":8,"p":["Commonality: Lochhead presents romantic, family and friendship relationships (1) to explore grief, jealousy and loneliness (1)","Chosen poem: a detailed comment on a relationship (2)","Last Supper: the women behaving as predators shows a toxic side of some female friendships","My Rival's House: the visit shows how a mother–son relationship can be overbearing and possessive","Box Room: the mother's domineering relationship with her son will harm the couple's relationship","For My Grandmother Knitting: the grandmother's need to keep knitting shows a disconnect with a younger generation","The Spaces Between: enforced separation in lockdown shows loneliness without physical contact","Sorting Through: clearing her mother's clothes shows the impact of grief and memory"],"l":3,"h":"Romantic, family, friendship."}]},
"st_paterson":{"name":"Don Paterson","area":"poetry","questions":[{"q":"Which six Paterson poems are set?","o":["Waking with Russell, 11:00: Baldovan, The Circle, The Thread, The Swing, Why Do You Stay Up So Late?","Waking with Russell, Rain, Nil Nil, The Thread, The Circle, A Private Bottling","11:00: Baldovan, Two Trees, The Thread, Rain, The Swing, The Circle","Why Do You Stay Up So Late?, Two Trees, Nil Nil, The Thread, The Circle, Waking with Russell"],"l":1,"e":"The set list names these six."},{"q":"Many of the set Paterson poems are about…","o":["fatherhood and his young sons","the sea and fishing","war","Victorian London"],"l":1,"e":"Several poems address or describe his sons."},{"q":"In \"The Thread\", the image of the thread suggests…","o":["the fragile, precarious hold of a child on life","sewing","a fishing line","a telephone wire"],"l":2,"e":"Specimen guidance: the 'thread' fastening Jamie to life."},{"q":"\"Waking with Russell\" shows the speaker…","o":["committing himself to nurture and protect his newborn son","arguing with a friend","waking up late for work","missing his father"],"l":2,"e":"From the specimen guidance."},{"q":"\"11:00: Baldovan\" describes…","o":["two boys on a trip who return to find the world seems to have moved on without them","a football match","a hospital birth","a wedding"],"l":2,"e":"Guidance: life moves on without us; individuals are forgotten."},{"q":"\"Why Do You Stay Up So Late?\" is the poet's answer to…","o":["his son's question — comparing writing poems to finding stones in a rockpool","his wife's complaint","a teacher","a journalist"],"l":2,"e":"2026 marking instructions: 'This is how you knew the ones to keep.'"},{"q":"Which central concern does the specimen final question focus on for Paterson?","o":["The fragility of human life","Scottish heritage","Class and work","The supernatural"],"l":2,"e":"\"Discuss how the poet explores the fragility of human life.\""},{"q":"\"The Circle\" links a child drawing a circle with…","o":["the difficult circumstances of his birth and how close humans are to death","a wedding ring","the moon","a football"],"l":2,"e":"Specimen guidance quotes the danger at birth."},{"q":"Recurring central concerns in Paterson's set poems include…","o":["parenthood, love, time, mortality and the fragility of life, and creativity","factory work and class","war guilt","Glasgow's tenements"],"l":2,"e":"From official guidance."},{"q":"In \"The Swing\", the idea of a swing suggests…","o":["the lack of certainty and permanence in human hopes and experience","childhood fun only","wealth","a holiday"],"l":3,"e":"From the specimen marking instructions."},{"q":"Don Paterson is from…","o":["Dundee","Paisley","Orkney","Lahore"],"l":2,"e":"Baldovan is on the edge of Dundee."},{"q":"FINAL QUESTION PRACTICE (8 marks)\n\nBy referring to one Paterson poem you have studied and to at least one other poem by Paterson, discuss how the poet explores the fragility of human life.\n\n(2 commonality, 2 extract, 4 elsewhere.)","m":8,"p":["Commonality: the threat of death is ever-present in our sense of ourselves (1); anticipating or surviving that threat is a powerful force at all stages of life (1)","Chosen poem: a detailed comment (2)","The Thread: the 'thread' fastening Jamie to life shows life's precariousness","The Circle: the difficulties of his birth show how close humans are to death even at birth","The Swing: the swing's instability suggests uncertainty in human hopes","Why Do You Stay Up So Late?: the difficulty of telling which experiences 'are dead and which have the surprise' — fragility of creativity","11:00: Baldovan: returning to a world that has moved on — individuals are forgotten","Waking with Russell: the vulnerability of the newborn makes the speaker commit to protect him"],"l":3,"h":"Birth, childhood, time, creativity."}]},
"st_dharker":{"name":"Imtiaz Dharker","area":"poetry","questions":[{"q":"Which six Dharker poems are set?","o":["Bairn, Bloom, Letters to Glasgow, Send This, Stitch, The Knot","Tissue, Bairn, Bloom, Blessing, The Knot, Stitch","Tissue, Blessing, Send This, Bloom, Bairn, Living Space","Living Space, Bairn, Bloom, Letters to Glasgow, Tissue, Stitch"],"l":1,"e":"Dharker was added to the list for 2025–26 with these six poems."},{"q":"Where did Imtiaz Dharker grow up?","o":["Glasgow (she was born in Lahore, Pakistan)","Dundee","Orkney","London"],"l":1,"e":"Her poems often explore identity, home and family."},{"q":"\"Bairn\" and \"Bloom\" both focus on…","o":["a baby and the overwhelming significance of new life","a city at night","a war","a train journey"],"l":2,"e":"Guidance: wonder at the baby's presence."},{"q":"In \"Bloom\", the baby is compared to \"a leaf among thousands on a tree\". This suggests…","o":["the baby's ordinariness — set against its unique importance to the speaker","that the baby is unwell","autumn","that the baby is unwanted"],"l":2,"e":"Specimen guidance."},{"q":"Which line from \"Bloom\" (quoted in the 2026 marking instructions) shows the baby's overwhelming significance?","o":["\"Holding you, I hold the world\"","\"Look at me now\"","\"So who's the monster?\"","\"I'm master of nothing I survey\""],"l":2,"e":"The contrast with \"You are nothing but yourself\" highlights parental love."},{"q":"In \"Stitch\", the two cardigans (one blue and machine-made, one red and hand-made) represent…","o":["two different mother–daughter relationships — one calmer, one fierce and possessive","rich and poor","Scotland and England","summer and winter"],"l":2,"e":"From the specimen and 2026 marking instructions."},{"q":"In \"Send This\", the \"wrong key\" with which the speaker tries to unlock the city represents…","o":["the gap between romantic memories of the past city and its reality now","a burglary","a lost house","a prison"],"l":2,"e":"Specimen guidance."},{"q":"\"The Knot\" moves from a childhood picnic to…","o":["a later, silent family meeting after the mother has gone — the impact of loss","a wedding","a sailing trip","a school exam"],"l":2,"e":"Untying the cloth represents tightly tied feelings."},{"q":"In \"Letters to Glasgow\", the train is used to suggest…","o":["the forward movement of life, contrasted with dreamy memories of the past","danger","wealth","a holiday"],"l":2,"e":"2026 marking instructions."},{"q":"Common central concerns in Dharker's set poems include…","o":["family relationships, love, memory, heritage, loss and change","war guilt","factory work","the supernatural"],"l":2,"e":"From official guidance."},{"q":"Using the Scots word \"Bairn\" as a title suggests…","o":["a connection between the speaker's identity, the child and Scotland/language","that the poem is about farming","that the child is a boy","nothing in particular"],"l":3,"e":"Dharker's poems often explore belonging and language."},{"q":"FINAL QUESTION PRACTICE (8 marks)\n\nBy referring to one Dharker poem you have studied and to at least one other poem by Dharker, discuss how the poet uses imagery and/or symbolism to explore central concerns.\n\n(2 commonality, 2 extract, 4 elsewhere.)","m":8,"p":["Commonality: Dharker uses images/symbols such as colours, journeys and objects (1) to explore family relationships, love and memory (1)","Chosen poem: a detailed comment on an image/symbol (2)","Bloom: 'leaf among thousands on a tree' — the baby's ordinariness against its unique importance","The Knot: untying the picnic cloth represents tightly tied feelings in adult family relationships","Stitch: the two cardigans represent two contrasting family relationships","Send This: the 'wrong key' represents the gap between memories of the city and its reality","Letters to Glasgow: the future as a fellow passenger on the train represents the transitory nature of experience","Bairn: new morning light and snow represent wonder and a transformed world"],"l":3,"h":"Colours, journeys, objects."}]},
"st_jamie":{"name":"Kathleen Jamie","area":"poetry","questions":[{"q":"Which six Jamie poems are set?","o":["Crossing the Loch, Mr and Mrs Scotland are Dead, Ospreys, Song of Sunday, The Morrow-bird, What the Clyde said, after COP26","The Queen of Sheba, Crossing the Loch, Ospreys, Skeins o Geese, Wee Baby, Fragment","Mr and Mrs Scotland are Dead, The Way We Live, Hagen, Crossing the Loch, Ospreys, Flashing Green","Song of Sunday, The Queen of Sheba, The Way We Live, Crossing the Loch, Ospreys, The Clyde"],"l":1,"e":"Jamie was added for 2025–26 with these six poems."},{"q":"Kathleen Jamie served as Scotland's Makar (national poet) from…","o":["2021 to 2024","2011 to 2016","2004 to 2010","1999 to 2003"],"l":1,"e":"She succeeded Jackie Kay."},{"q":"\"Crossing the Loch\" recalls…","o":["a group of young friends rowing across a loch at night, amazed by light in the water","a ferry to Orkney","a swimming race","a storm at sea that sinks a ship"],"l":2,"e":"Specimen guidance: 'like a twittering nest' — huddled, scared, fascinated."},{"q":"\"Mr and Mrs Scotland are Dead\" is set at…","o":["a council tip/dump where a dead couple's belongings have been thrown out","a funeral","a castle","the Scottish Parliament"],"l":2,"e":"It questions how we preserve ordinary Scottish heritage."},{"q":"In \"Ospreys\", the birds have flown from…","o":["Senegal","Norway","Canada","Iceland"],"l":2,"e":"2026 marking instructions: 'beating up from Senegal' — a long, arduous journey."},{"q":"\"Song of Sunday\" uses the image of tatties peeled \"lovelessly\" to suggest…","o":["the joyless, necessary domestic work done by women — traditional gender roles","a happy family meal","the poet's love of cooking","farming"],"l":2,"e":"From the specimen guidance."},{"q":"In \"The Morrow-bird\", a bird 'speaks' to…","o":["the Scottish Parliament","a child","a fisherman","the sea"],"l":2,"e":"Guidance: Scotland must embrace its multi-ethnicity to flourish."},{"q":"\"What the Clyde said, after COP26\" uses which main technique?","o":["Personification of the river","Dramatic monologue by a soldier","A ballad about a knight","Free verse about a classroom"],"l":2,"e":"The river speaks about its importance to Glasgow and fears for its future."},{"q":"Recurring concerns in Jamie's set poems include…","o":["the natural world, Scotland's landscape and heritage, community, change and the future","war guilt","Victorian duality","factory work"],"l":2,"e":"From the specimen guidance."},{"q":"In \"Ospreys\", Scots words such as \"teuchit storm\" suggest…","o":["the speaker's knowledge of how harsh and unexpected Scottish weather can be","that the poem is set in England","humour about birds","a formal tone"],"l":3,"e":"2026 marking instructions."},{"q":"FINAL QUESTION PRACTICE (8 marks)\n\nBy referring to one Jamie poem you have studied and to at least one other poem by Jamie, discuss how the poet uses imagery and/or symbolism to explore central concerns.\n\n(2 commonality, 2 extract, 4 elsewhere.)","m":8,"p":["Commonality: imagery/symbolism of the natural world, human behaviour and setting (1) conveys concerns such as Scotland's landscape, heritage and important personal experiences (1)","Chosen poem: a detailed comment (2)","Song of Sunday: tatties peeled 'lovelessly' symbolise joyless women's work and traditional gender roles","Mr and Mrs Scotland are Dead: belongings scattered at the tip — how we preserve Scotland's heritage","What the Clyde said, after COP26: personified river — its importance to Glasgow and concern for its future","Ospreys: 'raw wind' faced by the birds — resilience of the natural world","The Morrow-bird: the bird speaking to parliament — Scotland must embrace its multi-ethnicity"],"l":3,"h":"Nature, human behaviour, setting."}]},
"st_coll":{"name":"Higher Scottish Poetry Collection","area":"poetry","questions":[{"q":"Which poems are in the Higher Scottish poetry collection?","o":["Thomas the Rhymer, Composed in August, The Bonnie Broukit Bairn, Summit of Corrie Etchachan, Da Clearance, 33","A Red, Red Rose, Lochinvar, The Twa Corbies, Auntie, Little Girls, The Bonnie Earl o' Moray","Tam o' Shanter, To a Mouse, Thomas the Rhymer, Lochinvar, Da Clearance, 33","Composed in August, A Red, Red Rose, Auntie, Little Girls, 33, Lochinvar"],"l":1,"e":"The second list is the National 5 collection — don't mix them up."},{"q":"Who wrote \"Composed in August\"?","o":["Robert Burns","Walter Scott","Hugh MacDiarmid","Nan Shepherd"],"l":1,"e":"Burns contrasts the harmony of nature with \"Tyrannic man's dominion\" and the hunter's guns."},{"q":"\"Thomas the Rhymer\" is…","o":["a traditional ballad in which True Thomas is carried off by the Queen of Elfland","a modern free-verse poem","a sonnet by Burns","a poem about a ship"],"l":2,"e":"He serves her seven years and receives \"the tongue that can never lie\"."},{"q":"In \"Thomas the Rhymer\", the Queen shows three roads. Which leads to Elfland?","o":["The \"bonny road\" that winds about the fernie brae","The narrow road beset with thorns","The braid, braid road","The road by the sea"],"l":2,"e":"The narrow road = righteousness; the broad road = wickedness; the bonny road = Elfland."},{"q":"\"The Bonnie Broukit Bairn\" by Hugh MacDiarmid compares the Earth to…","o":["a neglected, dirty-faced child, more precious than the splendid planets","a ship","a queen","a garden"],"l":2,"e":"Specimen guidance: Mars and Venus splendid; the mucky, neglected earth valued more."},{"q":"Hugh MacDiarmid is associated with…","o":["the Scottish Renaissance and writing in Scots","Romantic ballads","the Gaelic revival only","Shetland dialect"],"l":2,"e":"MacDiarmid (Christopher Murray Grieve) championed modern poetry in Scots."},{"q":"\"Summit of Corrie Etchachan\" by Nan Shepherd is set in…","o":["the Cairngorm mountains","Shetland","Glasgow","the Clyde"],"l":2,"e":"Specimen guidance contrasts a 'blue world, far, unattainable' with 'this grey plateau, rock-strewn'."},{"q":"\"Da Clearance\" by Rhoda Bulter is written in…","o":["Shetland dialect","Gaelic","Standard English","Doric"],"l":2,"e":"It contrasts a thriving crofting community with the emptiness after the people were cleared."},{"q":"\"Da Clearance\" criticises…","o":["landowners who cleared people from the land for profit, destroying a way of life","the weather","fishermen","the church"],"l":2,"e":"2026 guidance: bare walls represent the community's destruction by the desire for profit."},{"q":"In \"33\" by MacGillivray, the chandelier made of driftwood \"from all the world's shipwrecks\" suggests…","o":["that even human loss and despair can come together into something resilient","that the speaker collects antiques","a party","that ships are safe"],"l":2,"e":"From the 2026 marking instructions."},{"q":"A common technique the specimen paper asks about across the collection is…","o":["contrast — e.g. life/death, nature/humanity, peace/conflict","onomatopoeia only","rhyme scheme","dialogue"],"l":2,"e":"The specimen final question: \"discuss how contrast is used to explore central concerns\"."},{"q":"In \"Composed in August\", \"Thick flies the skimming swallow\" and \"the silent moon\" belong to the evening walk with Peggy. The poem contrasts this tenderness with…","o":["the slaughter of birds by hunters (\"The sportsman's joy, the murd'ring cry\")","city noise","a storm at sea","a battle"],"l":3,"e":"Burns sets love and harmony against humanity's cruelty to nature."},{"q":"FINAL QUESTION PRACTICE (8 marks)\n\nBy referring to one poem you have studied and to at least one other poem from the Higher Scottish poetry collection, discuss how contrast is used to explore central concerns.\n\n(2 commonality, 2 extract, 4 elsewhere.)","m":8,"p":["Commonality: the poets use contrast such as life and death, peace and conflict, nature and humanity (1) to highlight cruelty, power, the importance of ordinary life and the imagination (1)","Chosen poem: a detailed comment on a contrast (2)","Composed in August: hunters' 'slaught'ring guns' versus the birds' harmony — humanity's destructive power over nature","Thomas the Rhymer: the thorny road to heaven versus the 'bonny road' to Elfland — the temptation of mystery against strict 'proper' behaviour","Da Clearance: the thriving community versus the deserted village — landowners' lack of concern for people and heritage","Summit of Corrie Etchachan: 'blue world, far, unattainable' versus 'this grey plateau, rock-strewn' — the value of real experience","33: 'all the world's shipwrecks' versus 'one tear' — each individual loss matters","The Bonnie Broukit Bairn: splendid Mars and Venus versus the neglected earth — valuing ordinary human life"],"l":3,"h":"Life/death, peace/conflict, nature/humanity."}]},
"pf_rules":{"name":"Portfolio–Writing: Rules & Marking","area":"pf","questions":[{"q":"How many pieces of writing go in the Higher English portfolio (current specification)?","o":["One — either broadly creative or broadly discursive","Two — one creative and one discursive","Three","Four short pieces"],"l":1,"e":"The September 2025 course specification: candidates produce one written text."},{"q":"How many marks is the portfolio–writing worth in the course award?","o":["30 (one piece marked out of 15, doubled)","15","20","40"],"l":1,"e":"15 marks are available for the piece; the 30% weighting is achieved by doubling."},{"q":"What is the maximum word count for the portfolio piece?","o":["1,300 words","1,000 words","1,500 words","2,000 words"],"l":1,"e":"No more than 1,300 words; there is no minimum."},{"q":"What happens if your piece exceeds the word limit by more than 10%?","o":["A penalty is applied","Nothing — it's guidance only","It is not marked at all","You lose 1 mark per extra word"],"l":2,"e":"The specification: a penalty applies if the count exceeds the maximum by more than 10%."},{"q":"Is there a minimum word count?","o":["No — full marks can be achieved in a shorter piece if appropriate (e.g. poetry)","Yes, 650 words","Yes, 1,000 words","Yes, 500 words"],"l":2,"e":"The specification says there is no minimum."},{"q":"Where must the first draft be written?","o":["In class, under supervision, over a period of up to 4 hours","At home","In the exam hall","Anywhere — no rules"],"l":2,"e":"First draft in class under supervision; it may be spread over several sessions."},{"q":"How many drafts can your teacher give feedback on?","o":["One","Two","Three","As many as you like"],"l":2,"e":"It is not acceptable for a teacher to give feedback on more than one draft."},{"q":"Which of these is your teacher NOT allowed to provide?","o":["Corrections of spelling/punctuation errors or specific rewording","General feedback on one draft","An initial discussion about focus and genre","Advice on how to find information"],"l":2,"e":"The specification lists what is and isn't acceptable \"reasonable assistance\"."},{"q":"Which counts as plagiarism under the specification?","o":["Using generative AI for anything other than suggesting potential source material","Using your own research with footnotes","Discussing ideas with your teacher","Writing about your own experiences"],"l":2,"e":"The specification lists AI misuse, copying without citation and missing quotation marks as plagiarism."},{"q":"How must sources for discursive writing be acknowledged?","o":["In footnotes or a list at the end, with specific details","They don't need to be","Only in the title","By telling your teacher verbally"],"l":2,"e":"\"Any sources consulted for discursive writing must be acknowledged in footnotes or in a list at the end.\""},{"q":"What is the top mark band for the portfolio piece?","o":["15–13","20–19","30–27","12–10"],"l":2,"e":"Portfolio bands: 15–13, 12–10, 9–7, 6–4, 3–1, 0."},{"q":"What is required for a piece to reach the 9–7 band or above?","o":["Consistent technical accuracy — few errors; paragraphs, sentences and punctuation mostly accurate","At least 1,200 words","A creative piece","Footnotes"],"l":3,"e":"The specification: consistent technical accuracy is a requirement for the 9–7 band."},{"q":"The portfolio is marked in terms of…","o":["content and style","length and spelling only","handwriting","research only"],"l":2,"e":"Markers assess content and style holistically."},{"q":"Who marks the portfolio?","o":["It is submitted to Qualifications Scotland (SQA) for external marking","Your teacher only","Your classmates","Nobody — it is pass/fail"],"l":2,"e":"Evidence is submitted for external marking."},{"q":"Is the spoken language performance graded with marks?","o":["No — it is achieved/not achieved, but you must achieve it to gain the course award","Yes, out of 20","Yes, out of 10","It is optional"],"l":2,"e":"Spoken language is compulsory and assessed on an achieved/not achieved basis."},{"q":"How many aspects of spoken language performance must you achieve?","o":["Four","Two","Three","Six"],"l":2,"e":"The specification lists four aspects, including selecting detailed and complex spoken language and listening skills."},{"q":"Which activity can count towards the spoken language performance?","o":["A group discussion or an individual presentation","Only a written essay","Only a reading test","Only a poem recital"],"l":2,"e":"The specification: at least one of a group discussion/discussion-based activity or a prepared presentation (answering audience questions)."}]},
"pf_creative":{"name":"Broadly Creative Writing","area":"pf","questions":[{"q":"Which of these is broadly creative writing?","o":["A personal/reflective essay, short story, poem or drama script","An argumentative essay","A report","A persuasive essay"],"l":1,"e":"The specification lists these creative types."},{"q":"In the creative mark grid, the 15–13 band asks for…","o":["\"strong creative qualities\", \"skilful command of the genre\" and ideas explored with mature reflection or insight","at least three characters","a happy ending","rhyme throughout"],"l":2,"e":"From the broadly creative band descriptors."},{"q":"A personal reflective essay should…","o":["explore a real experience with honesty, insight and reflection on its significance","tell a story with no feelings","argue both sides of an issue","give a list of facts"],"l":2,"e":"The grid rewards \"a strong sense of the writer's personality and individuality\"."},{"q":"What is the difference between recounting and reflecting?","o":["Recounting tells what happened; reflecting explores what it meant, how you felt then and now","There is no difference","Reflecting means using mirrors","Recounting is always better"],"l":2,"e":"Reflection is what lifts a personal essay into the top bands."},{"q":"Which opening is most likely to engage a reader in a short story?","o":["Starting in the middle of the action or with an intriguing detail","\"Once upon a time…\"","\"This is a story about me.\"","A long description of the weather"],"l":2,"e":"In medias res or a striking image hooks the reader."},{"q":"\"Show, don't tell\" means…","o":["let actions, dialogue and detail reveal feelings rather than stating them","describe everything in a list","tell the reader the moral","avoid description"],"l":2,"e":"E.g. \"Her hands shook as she folded the letter\" rather than \"She was nervous\"."},{"q":"Which structural device can make a personal essay feel crafted?","o":["A cyclical structure, returning at the end to an opening image","Using no paragraphs","Repeating the title","A word count at the end"],"l":2,"e":"Crafted structure \"enhances the purpose/meaning\" — a top-band descriptor."},{"q":"A set of thematically linked poems can be submitted as…","o":["a broadly creative piece","a discursive piece","a report","it cannot be submitted"],"l":2,"e":"The specification explicitly allows \"a poem or set of thematically linked poems\"."},{"q":"What does \"thematic concerns which are skilfully introduced and developed\" mean in practice?","o":["The piece has a clear underlying idea (e.g. loss, identity) that grows through the writing","The piece has a title","The piece uses lots of themes briefly","The piece is long"],"l":3,"e":"Themes should be developed, not just mentioned."},{"q":"Which language features help creative writing gain marks for style?","o":["Precise word choice, imagery, varied sentence structure, effective dialogue, sensory detail","Lots of exclamation marks","Text speak","Very long paragraphs only"],"l":2,"e":"The style row rewards linguistic features \"used skilfully to create strong impact\"."},{"q":"Plan a reflective personal essay about a moment that changed how you saw someone in your family. Write a plan with an opening, three middle sections and an ending.","m":4,"p":["An engaging opening (striking image, line of dialogue or moment in medias res)","A clear focus on one significant experience, described with sensory detail","Reflection on feelings at the time AND now — insight / self-awareness","A structure that develops the theme (e.g. cyclical ending or a final insight)","Notes on language features to use (imagery, varied sentence lengths, dialogue)"],"l":2,"h":"Think: hook, the moment, then and now, insight."}]},
"pf_discursive":{"name":"Broadly Discursive Writing","area":"pf","questions":[{"q":"Which of these is broadly discursive writing?","o":["An argumentative essay, persuasive essay, report or informative writing","A short story","A poem","A drama monologue"],"l":1,"e":"The specification lists these discursive types."},{"q":"What is the difference between an argumentative and a persuasive essay?","o":["Argumentative weighs both sides before a balanced conclusion; persuasive argues one side forcefully","There is no difference","Persuasive essays have no evidence","Argumentative essays are fiction"],"l":2,"e":"Both need evidence and a clear line of thought."},{"q":"In the discursive mark grid, the 15–13 band asks for…","o":["\"strong and sustained line of thought/convincing stance\" and \"evidence of skilful research and selection\"","at least 10 statistics","a story","a happy ending"],"l":2,"e":"From the broadly discursive band descriptors."},{"q":"Why must you acknowledge sources in discursive writing?","o":["It is required, and unacknowledged copying counts as plagiarism","It makes the piece longer","Markers like long lists","It is optional"],"l":2,"e":"Sources must be listed in footnotes or at the end."},{"q":"A good discursive topic is…","o":["focused and debatable, e.g. \"Should Scotland ban disposable vapes?\"","very broad, e.g. \"The world\"","a plot summary of a film","an anecdote with no issue"],"l":2,"e":"A narrow, arguable question supports a sustained line of thought."},{"q":"Which technique helps an argumentative essay feel balanced?","o":["Presenting counter-arguments fairly and then evaluating/rebutting them","Ignoring the other side","Using only emotive language","Writing only in the first person"],"l":2,"e":"Evaluating both sides shows \"objectivity/insight\"."},{"q":"Which persuasive technique is most likely to be used well in a discursive piece?","o":["Rhetorical questions, direct address, emotive language backed by evidence, a strong conclusion","Lots of slang","No paragraphs","Dialogue between characters"],"l":2,"e":"Persuasive force is rewarded when supported by research."},{"q":"What does a strong conclusion to a discursive essay do?","o":["Draws the argument together and states a clear, justified overall stance","Introduces new evidence","Repeats the introduction word for word","Ends with \"The End\""],"l":2,"e":"A convincing stance is a top-band descriptor."},{"q":"Why is copying statistics without comment weak?","o":["Research must be selected and used to support the line of thought — evidence needs analysis","Statistics are banned","Markers can't read numbers","It makes the piece too short"],"l":3,"e":"\"Skilful research and selection\" means evidence is chosen and explained."},{"q":"Topic sentences in discursive writing should…","o":["make a clear point that moves the argument forward","tell a story","quote a source with no comment","ask a question every time"],"l":2,"e":"They help create a clear structure."},{"q":"Write a plan for an argumentative essay on: \"Should mobile phones be banned in Scottish secondary schools?\" Include an introduction, at least two points for each side, and a conclusion.","m":4,"p":["Introduction outlining the issue and its relevance (and any context, e.g. current guidance)","At least two developed points FOR a ban (e.g. concentration, bullying, wellbeing) with planned evidence","At least two developed points AGAINST (e.g. safety, learning uses, responsibility) with planned evidence","Conclusion giving a clear, justified overall stance","Planned sources to acknowledge in footnotes or a list"],"l":2,"h":"Balanced, researched, clear stance at the end."}]},
"term_lit":{"name":"Literary Techniques","area":"term","questions":[{"q":"Alliteration is…","o":["repetition of the same consonant sound at the start of nearby words","repetition of vowel sounds","a comparison","a contradiction"],"l":1,"e":"E.g. \"slaught'ring guns\" / \"fractious bairns\" — sound patterns create emphasis."},{"q":"Onomatopoeia is…","o":["a word that imitates the sound it describes","a repeated phrase","a type of rhyme","exaggeration"],"l":1,"e":"E.g. \"crump\", \"hiss\", \"clatter\"."},{"q":"Juxtaposition is…","o":["placing two contrasting things side by side for effect","repeating a word","using a question","giving human qualities to objects"],"l":2,"e":"Contrast highlights differences."},{"q":"Symbolism is…","o":["using an object, colour or image to represent a wider idea","a sound effect","a type of narrator","a list of three"],"l":2,"e":"E.g. MacCaig's Schiehallion symbolising life's challenges."},{"q":"Irony is…","o":["a contrast between what is said/expected and what is meant/happens","a type of rhyme","a stage direction","a simile"],"l":2,"e":"Situational, verbal and dramatic irony are all common."},{"q":"An allusion is…","o":["a reference to another text, myth, event or person","a hidden rhyme","a contradiction","a dialect word"],"l":2,"e":"E.g. Duffy's \"Mrs Midas\" alludes to the Greek myth."},{"q":"A motif is…","o":["a recurring image, idea or symbol in a text","the main character","the setting","the final scene"],"l":2,"e":"Tracking motifs helps with final-question 'elsewhere' comments."},{"q":"Euphemism is…","o":["a mild word or phrase used in place of something harsh or embarrassing","a harsh insult","a repeated sound","a long sentence"],"l":2,"e":"E.g. \"passed away\" for \"died\"."},{"q":"Pathos is…","o":["the quality in a text that evokes pity or sadness","a type of rhyme","humour","a narrative viewpoint"],"l":2,"e":"Pathos is often created by vulnerable characters."},{"q":"Hyperbole is…","o":["deliberate exaggeration","understatement","a pun","a rhetorical question"],"l":2,"e":"E.g. \"I've waited an eternity\"."},{"q":"Paradox is…","o":["a statement that seems contradictory but reveals a truth","a simple contradiction with no meaning","a long list","a type of setting"],"l":2,"e":"E.g. \"the more you know, the less you understand\"."},{"q":"A pun is…","o":["a play on words with more than one meaning","a type of stanza","a stage direction","a metaphor"],"l":2,"e":"E.g. Sadie's play on \"shy\" in The Slab Boys (2026 marking instructions)."},{"q":"Anaphora is…","o":["repetition of a word or phrase at the start of successive clauses","a type of rhyme","an echo at the end of a poem","a kind of narrator"],"l":2,"e":"It builds rhythm and emphasis."},{"q":"Emotive language is…","o":["language chosen to provoke a strong emotional reaction","technical vocabulary","neutral language","dialect"],"l":2,"e":"Common in persuasive writing and journalism."},{"q":"Bathos (anticlimax) is…","o":["a sudden shift from the serious/elevated to the trivial","an intense climax","a sad ending","a formal tone"],"l":3,"e":"Often used for humour or satire."}]},
"term_poetic":{"name":"Poetic Terms","area":"term","questions":[{"q":"Rhyme scheme is…","o":["the pattern of rhymes at the ends of lines, labelled ABAB etc.","the number of lines","the title","the speaker"],"l":1,"e":"Rhyme can create musicality, closure or emphasis."},{"q":"A couplet is…","o":["two consecutive lines, often rhyming","a group of four lines","a whole poem","a pause"],"l":1,"e":"A rhyming couplet can close a poem with emphasis."},{"q":"A quatrain is…","o":["a four-line stanza","a two-line stanza","a fourteen-line poem","a three-line stanza"],"l":2,"e":"Ballads such as \"Thomas the Rhymer\" use quatrains."},{"q":"A ballad is…","o":["a narrative poem, often in quatrains with a refrain, from oral tradition","a sonnet","a free-verse diary","a play"],"l":2,"e":"Traditional Scottish ballads tell dramatic stories."},{"q":"Iambic pentameter is…","o":["a line of ten syllables in five unstressed/stressed pairs","a line of four beats","free verse","a rhyming couplet"],"l":2,"e":"Common in Shakespeare and sonnets."},{"q":"Internal rhyme is…","o":["rhyme within a single line","rhyme at the end of lines","no rhyme","a repeated line"],"l":2,"e":"E.g. \"Thro' lofty groves the cushat roves\" in Burns's \"Composed in August\"."},{"q":"Half rhyme (slant rhyme) is…","o":["near rhyme where sounds are similar but not identical","perfect rhyme","no rhyme at all","rhyme within a line"],"l":2,"e":"Can create a sense of unease or incompleteness."},{"q":"A refrain is…","o":["a line or phrase repeated, often at the end of stanzas","the first line","the title","a single word"],"l":2,"e":"Refrains add emphasis and musicality."},{"q":"End-stopped lines are…","o":["lines ending with punctuation, creating a pause","lines that run on","lines with no punctuation at all","lines that rhyme internally"],"l":2,"e":"They contrast with enjambment."},{"q":"Apostrophe (as a poetic device) is…","o":["addressing someone absent, dead, or an object/abstract idea","a punctuation mark only","a type of rhyme","a narrative poem"],"l":2,"e":"E.g. Burns addresses his love directly in \"A Red, Red Rose\": \"my bonie lass\"."},{"q":"Tone in a poem is shown by…","o":["word choice, imagery, rhythm, punctuation and structure","the title only","the length only","the font"],"l":2,"e":"Analyse how tone shifts across the poem."},{"q":"Why might a poet use a short final line or one-line final stanza?","o":["To isolate and emphasise a key idea or sense of finality","To save space","Because they ran out of ideas","To rhyme"],"l":3,"e":"Position adds weight."},{"q":"Persona means…","o":["the voice or character speaking the poem","the poet's real name","the reader","the publisher"],"l":2,"e":"Duffy's monologues use personas such as Havisham."}]},
"term_drama":{"name":"Dramatic Terms","area":"term","questions":[{"q":"Dialogue is…","o":["the speech exchanged between characters","the stage set","the lighting plan","the cast list"],"l":1,"e":"Dialogue reveals character and conflict."},{"q":"Exposition is…","o":["the opening part that introduces characters, setting and situation","the climax","the interval","the ending"],"l":2,"e":"E.g. the first scene of The Slab Boys introduces the slab room and its workers."},{"q":"Rising action is…","o":["the series of events that build tension towards the climax","the ending","a flashback","an aside"],"l":2,"e":"It develops the central conflict."},{"q":"A protagonist is…","o":["the main character","the villain","a minor character","the director"],"l":2,"e":"The antagonist opposes the protagonist."},{"q":"Comic relief is…","o":["a humorous scene or character that lightens a serious play","a sad ending","a stage direction","the climax"],"l":2,"e":"It can also highlight tragedy by contrast."},{"q":"Naturalism/realism in drama means…","o":["presenting life realistically — everyday settings, speech and situations","using magic and myth","verse speech","masks"],"l":2,"e":"Men Should Weep's tenement setting is naturalistic."},{"q":"\"In medias res\" means…","o":["starting in the middle of the action","at the end","a dream","a song"],"l":2,"e":"Sequamur begins with the memorial already being prepared."},{"q":"A \"set\" is…","o":["the physical scenery and furniture on stage","the script","the audience","the interval"],"l":2,"e":"A single set can create claustrophobia."},{"q":"Props are…","o":["objects used by actors on stage","costumes","lighting","stage directions"],"l":2,"e":"Props can become symbolic (e.g. a letter or plaque)."},{"q":"Why might a playwright use flashbacks or ghosts on stage?","o":["To show memory, guilt or the past haunting the present","To make the play shorter","To save money","To confuse the audience"],"l":3,"e":"Sequamur uses memories and ghosts of pupils."},{"q":"A playwright's use of dialect in dialogue mainly…","o":["creates realism and identity, rooting characters in a place and class","makes the play harder","shows ignorance","is a mistake"],"l":2,"e":"Common in Scottish drama."}]},
};
const FLASHCARDS={"term":[{"term":"Metaphor","def":"A direct comparison: one thing IS another.\nAnalyse: literal root → how it applies → effect."},{"term":"Simile","def":"A comparison using \"like\" or \"as\".\nE.g. \"like a twittering nest\" (Jamie, Crossing the Loch)."},{"term":"Personification","def":"Giving human qualities to something non-human.\nE.g. the Clyde 'speaks' in Jamie's COP26 poem."},{"term":"Word choice","def":"A carefully chosen word whose connotations convey the writer's ideas/attitude.\nQuote → connotations → link to meaning."},{"term":"Connotation","def":"What a word suggests or implies beyond its literal (denotative) meaning."},{"term":"Tone","def":"The writer's attitude: e.g. sarcastic, nostalgic, angry, bitter, sincere, dismissive."},{"term":"Register","def":"The level of formality: formal, informal, colloquial, slang.\nA sudden shift is deliberate — comment on it."},{"term":"Alliteration","def":"Repetition of initial consonant sounds in nearby words — draws attention, creates rhythm/sound effects."},{"term":"Assonance","def":"Repetition of vowel sounds — can slow pace or create mood."},{"term":"Sibilance","def":"Repeated \"s\" sounds — hissing, menace or softness.\nE.g. Medusa's 'soured, stank' (2026 MI)."},{"term":"Onomatopoeia","def":"A word imitating its sound.\nE.g. 'crump o monny feet' (Da Clearance)."},{"term":"Oxymoron","def":"Two contradictory terms together.\nE.g. \"Beloved sweetheart bastard\" (Havisham)."},{"term":"Juxtaposition","def":"Placing contrasting ideas side by side to highlight difference."},{"term":"Antithesis","def":"Contrasting ideas in balanced phrases.\n\"Clean on the motorway; filthy at the mine.\""},{"term":"Hyperbole","def":"Deliberate exaggeration for effect."},{"term":"Understatement","def":"Presenting something as less important than it is — often ironic."},{"term":"Irony","def":"A gap between what is said/expected and what is meant/happens."},{"term":"Sarcasm","def":"Cutting irony — saying the opposite to mock."},{"term":"Bathos / anticlimax","def":"A drop from the serious to the trivial — often comic or deflating."},{"term":"Symbolism","def":"An object/colour/image standing for a wider idea.\nE.g. the red door = individuality."},{"term":"Motif","def":"A recurring image or idea through a text."},{"term":"Allusion","def":"A reference to another text, myth or event.\nE.g. Mrs Midas → Greek myth."},{"term":"Pathetic fallacy","def":"Weather/setting reflecting mood or feelings."},{"term":"Foreshadowing","def":"Hints of future events."},{"term":"Enjambment","def":"A sentence running over a line break — momentum, or emphasis on the first word of the next line."},{"term":"Caesura","def":"A pause in the middle of a line (usually punctuation) — slows pace, adds emphasis."},{"term":"Volta","def":"A turn in thought or mood in a poem (often signalled by \"but\", \"yet\")."},{"term":"Dramatic monologue","def":"A poem spoken by a character (persona), revealing their personality and situation.\nE.g. Havisham, Medusa."},{"term":"Stanza","def":"A group of lines forming a unit — breaks can signal shifts in time or mood."},{"term":"Rhyme scheme","def":"Pattern of end rhymes (ABAB…). Can create closure, musicality or irony."},{"term":"Free verse","def":"Poetry without regular rhyme or metre."},{"term":"Ballad","def":"Narrative poem from oral tradition, often in quatrains.\nE.g. Thomas the Rhymer."},{"term":"Soliloquy","def":"A character alone on stage speaking private thoughts to the audience."},{"term":"Aside","def":"A brief remark to the audience unheard by other characters."},{"term":"Dramatic irony","def":"The audience knows something a character doesn't."},{"term":"Stage directions","def":"Instructions on setting, movement, delivery, lighting and sound — key evidence in drama."},{"term":"Climax","def":"The point of greatest tension where the central conflict comes to a head."},{"term":"Denouement","def":"The resolution after the climax, where outcomes are revealed."},{"term":"First-person narrator","def":"\"I\" — intimate but limited and possibly unreliable."},{"term":"Omniscient narrator","def":"Third-person narrator who knows all characters' thoughts."},{"term":"Mise-en-scène","def":"Everything in the film frame: setting, props, costume, lighting, positioning."},{"term":"Diegetic / non-diegetic sound","def":"Diegetic: within the film's world (dialogue, radio).\nNon-diegetic: added for the audience (score, voice-over)."},{"term":"Camera angles","def":"Low angle → power/threat. High angle → vulnerability. Close-up → emotion/significance."}],"ruae":[{"term":"RUAE paper","def":"30 marks · 1 h 30 min · two unseen non-fiction passages linked by theme · final question on both passages worth 5."},{"term":"Own-words questions","def":"\"Identify/explain… use your own words.\"\nNo marks for straight lifts. Gloss key words, keep the meaning."},{"term":"Analysis marking","def":"2 marks: detailed/insightful comment + quotation.\n1 mark: basic comment + quotation.\n0: quotation alone."},{"term":"Imagery method","def":"1. Literal root of the image\n2. How it applies to the subject\n3. What that conveys (attitude/idea)"},{"term":"Sentence structure checklist","def":"Lists · repetition · short/minor sentences · questions · inversion · climax/anticlimax · parallel structure · antithesis"},{"term":"Punctuation checklist","def":"Colon → explanation/list\nSemicolon → balance/contrast\nDash(es) → aside/dramatic addition\nInverted commas → sarcasm/distancing\nEllipsis → trailing off/pause"},{"term":"Link question method","def":"Quote/refer to the words that look BACK (to the previous idea) and the words that look FORWARD (to the new idea) — explain both."},{"term":"Final 5-mark question","def":"Identify three key areas of agreement (or disagreement).\n3 areas = 3 marks · + appropriate evidence = 4 · + detailed/insightful evidence = 5."},{"term":"Key area","def":"A big shared idea or stance — not shared vocabulary. Support with evidence from BOTH passages."},{"term":"Evaluate","def":"Judge effectiveness: analyse the feature, then explain why it works (e.g. how a conclusion links to earlier ideas)."},{"term":"Tone answers","def":"Name the tone precisely + analyse the language that creates it."},{"term":"Time plan (RUAE)","def":"~2 min per mark on Passage 1 questions; leave ~15 minutes to read Passage 2 and answer the final question."}],"essay":[{"term":"Critical Reading paper","def":"40 marks · 1 h 45 min\nSection 1 Scottish text (20) + Section 2 critical essay (20).\nDifferent genre in each section."},{"term":"Essay marking grid","def":"Bands: 20–19 · 18–16 · 15–13 · 12–10 · 9–6 · 5–0.\nKnowledge & understanding · analysis · evaluation · technical accuracy."},{"term":"Technical accuracy rule","def":"Few errors in spelling, grammar, punctuation, paragraphing; understood at first reading.\nIf not met (or irrelevant): max 9."},{"term":"Analysis words by band","def":"Perceptive (20–19) · detailed (18–16) · clear (15–13) · adequate (12–10) · limited (9–6)."},{"term":"Evaluation words by band","def":"Committed (20–19) · engaged (18–16) · clear (15–13) · adequate (12–10)."},{"term":"Introduction","def":"Title + writer + genre · key words of the question · brief context · line of argument."},{"term":"Body paragraph (PEAE)","def":"Point (answers question) → Evidence (short quote/reference) → Analysis (technique + effect) → Evaluation (link to question/text as a whole)."},{"term":"Conclusion","def":"Return to the question · summarise the line of thought · final evaluation of the text as a whole."},{"term":"Typical essay question shape","def":"\"Choose a [text] in which… By referring to appropriate techniques, briefly explain… and discuss how this contributes to your appreciation of the text as a whole.\""},{"term":"Genres for Section 2","def":"Drama · prose fiction · prose non-fiction · poetry · film & TV drama · language."},{"term":"Drama rubric features","def":"Characterisation, key scene(s), structure, climax, theme, plot, conflict, setting."},{"term":"Prose fiction rubric features","def":"Characterisation, setting, language, key incident(s), climax, turning point, plot, structure, narrative technique, theme, ideas, description."},{"term":"Poetry rubric features","def":"Word choice, tone, imagery, structure, content, rhythm, rhyme, theme, sound, ideas."},{"term":"Film & TV rubric features","def":"Use of camera, key sequence, characterisation, mise-en-scène, editing, setting, music/sound, special effects, plot, dialogue."},{"term":"Language rubric features","def":"Register, accent, dialect, slang, jargon, vocabulary, tone, abbreviation."}],"texts":[{"term":"Final Scottish text question (from 2026–27)","def":"8 marks = 2 commonality + 2 the extract + 4 elsewhere.\nInitial extract questions = 12 marks."},{"term":"Commonality","def":"What links the extract to the rest of the text/other poems in terms of the question — often 1 mark for the technique/feature + 1 for the central concerns."},{"term":"The Slab Boys","def":"John Byrne · 1957 · slab room of A.F. Stobo & Co., Paisley.\nPhil, Spanky, Hector, Alan, Curry, Jack Hogg, Lucille, Sadie.\nClass, ambition, authority, gender, youth."},{"term":"Sequamur","def":"Donald S Murray · Nicolson Institute, Stornoway · rector William J. Gibson.\n'Let us follow'.\nWar, remembrance, guilt, deception, authority."},{"term":"Men Should Weep","def":"Ena Lamont Stewart · 1930s Glasgow tenement.\nMaggie, John, Lily, Jenny, Alec, Isa, Bertie, Granny.\nPoverty, gender roles, family, class."},{"term":"Dr Jekyll and Mr Hyde","def":"R L Stevenson · 1886 · Victorian London.\nUtterson, Enfield, Lanyon, Poole, Carew.\nDuality, secrecy, reputation, good vs evil."},{"term":"The Sunlight Pilgrims","def":"Jenni Fagan · caravan park, Clachan Fells · winter 2020–21 ice age.\nDylan, Constance, Stella (Alistair).\nIdentity, acceptance, resilience, change."},{"term":"Iain Crichton Smith stories","def":"The Red Door · Mother and Son · The Painter · The Existence of the Hermit.\nIndividuality vs conformity; restrictions of island/village life."},{"term":"Scottish short story collection","def":"A Voice Spoke to Me at Night (McClory) · Things My Wife and I Found Hidden in Our House (Logan) · Andrina (Mackay Brown) · Death in a Nut (Williamson)."},{"term":"Carol Ann Duffy (Higher)","def":"Originally · Mrs Midas · In Mrs Tilscher's Class · Medusa · Havisham · Before You Were Mine.\nIdentity, growing up, love, betrayal, loss."},{"term":"Norman MacCaig (Higher)","def":"Aunt Julia · Hotel Room, 12th Floor · Basking Shark · On Lachie's Croft · Landscape and I · Old Highland Woman.\nHeritage, nature, time, human savagery."},{"term":"Liz Lochhead (Higher)","def":"My Rival's House · Last Supper · Box Room · For My Grandmother Knitting · The Spaces Between · Sorting Through.\nRelationships, change, grief, jealousy."},{"term":"Don Paterson (Higher)","def":"Waking with Russell · 11:00: Baldovan · The Circle · The Thread · The Swing · Why Do You Stay Up So Late?\nParenthood, time, fragility of life, creativity."},{"term":"Imtiaz Dharker (Higher)","def":"Bairn · Bloom · Letters to Glasgow · Send This · Stitch · The Knot.\nFamily, love, memory, heritage, loss."},{"term":"Kathleen Jamie (Higher)","def":"Crossing the Loch · Mr and Mrs Scotland are Dead · Ospreys · Song of Sunday · The Morrow-bird · What the Clyde said, after COP26.\nNature, heritage, community, the future."},{"term":"Higher Scottish poetry collection","def":"Thomas the Rhymer (ballad) · Composed in August (Burns) · The Bonnie Broukit Bairn (MacDiarmid) · Summit of Corrie Etchachan (Shepherd) · Da Clearance (Bulter) · 33 (MacGillivray)."},{"term":"Phil McCann","def":"Talented, rebellious slab boy; Art School rejects him; sacked, but cartwheels off — the power of youth."},{"term":"William J. Gibson","def":"Sequamur's rector; inspired by the classics, encouraged pupils to fight; later tormented by guilt."},{"term":"Maggie Morrison","def":"Holds the family together through poverty; finally takes control of her life."},{"term":"Mr Utterson","def":"Lawyer who investigates Hyde; keeps Jekyll's secret — secrecy corrupts even the respectable."},{"term":"Stella","def":"Twelve-year-old trans girl; resilient despite bullying and her father's refusal to accept her."},{"term":"Death in a Nut — key idea","def":"\"Bithout Death there is no life\" — death is part of the natural cycle."},{"term":"Composed in August — key contrast","def":"Nature's harmony (\"ev'ry kind their pleasure find\") vs \"Tyrannic man's dominion\" — the hunters' guns."}],"pf":[{"term":"Portfolio–writing","def":"ONE piece: broadly creative OR broadly discursive.\nMarked out of 15, doubled → 30 marks (30%)."},{"term":"Word limit","def":"Max 1,300 words; no minimum. More than 10% over = penalty."},{"term":"Drafting rules","def":"First draft in class under supervision (up to 4 hours). Teacher feedback on ONE draft only."},{"term":"Broadly creative types","def":"Personal/reflective essay · short story/episode · poem or linked poems · drama script."},{"term":"Broadly discursive types","def":"Argumentative essay · persuasive essay · report · transactional/informative writing."},{"term":"Portfolio bands","def":"15–13 · 12–10 · 9–7 · 6–4 · 3–1 · 0.\nConsistent technical accuracy needed for 9–7 and above."},{"term":"Sources & AI","def":"Acknowledge all sources (footnotes or list). Using generative AI for anything other than suggesting source material = plagiarism."},{"term":"Spoken language","def":"Achieved/not achieved — compulsory for the award. Four aspects; group discussion and/or presentation."},{"term":"Creative top band","def":"Strong attention to purpose/audience · strong creative qualities · skilful command of genre · mature reflection/insight · strong sense of personality."},{"term":"Discursive top band","def":"Strong understanding & engagement · skilful research and selection · strong, sustained line of thought/convincing stance."}]};
FLASHCARDS.all=[].concat(FLASHCARDS.term,FLASHCARDS.ruae,FLASHCARDS.essay,FLASHCARDS.texts,FLASHCARDS.pf);
const FC_DECKS=[["all","All cards"],["term","Techniques & terminology"],["ruae","RUAE skills"],["essay","Critical essay"],["texts","Scottish set texts"],["pf","Portfolio & spoken language"]];
const ESSAYS=[{"genre":"generic","text":"Any play","q":"Choose a play in which the conflict between two characters is an important feature. By referring to appropriate techniques, briefly explain the nature of the conflict and discuss how this contributes to your appreciation of the play as a whole.","plan":["Intro: title, playwright, the two characters, the nature of the conflict (values? power? class? love?), line of thought","Para 1 — establish the conflict early: first meeting/key exchange; analyse dialogue and stage directions","Para 2 — escalation: a key scene where tension rises; analyse structure (rising action), language, staging","Para 3 — climax of the conflict: what happens and how it is presented","Para 4 — resolution/consequences: who 'wins' and what this reveals","Evaluation in every paragraph: link the conflict to central concerns (e.g. power, gender, class)","Conclusion: how the conflict shapes your appreciation of the play as a whole"]},{"genre":"generic","text":"Any novel/short story","q":"Choose a novel or short story in which the setting in time and/or place is important. By referring to appropriate techniques, briefly explain why the setting is significant and discuss how this contributes to your appreciation of the text as a whole.","plan":["Intro: TAG + the setting (when and where) + why it matters","Para 1 — establishing description: analyse imagery/word choice that creates atmosphere","Para 2 — how the setting shapes characters' lives and choices","Para 3 — setting as symbol (e.g. a house, a city, weather)","Para 4 — setting at a key incident/climax","Evaluation: link setting to themes — isolation, class, freedom, decline","Conclusion: why the text could not work the same way anywhere else"]},{"genre":"generic","text":"Any poem","q":"Choose a poem in which the poet presents a persona and/or character for whom the reader feels sympathy. By referring to appropriate techniques, discuss how the poet's presentation of the persona/character provokes your sympathy and enhances your appreciation of the poem as a whole.","plan":["Intro: poem, poet, persona and their situation, why we feel sympathy","Para 1 — opening: voice/tone, first impressions created by word choice","Para 2 — imagery that reveals their suffering/inner life","Para 3 — structure: stanza shifts, line breaks, volta, final line","Para 4 — sound/rhythm and how it mirrors emotion","Evaluation: how sympathy deepens our understanding of a central concern","Conclusion: the poem as a whole"]},{"genre":"generic","text":"Any film or TV drama","q":"Choose a film or television drama which contains a particularly memorable or thrilling or disturbing sequence. By referring to appropriate techniques, briefly explain how the film or programme makers present this sequence and discuss how this contributes to your appreciation of the text as a whole.","plan":["Intro: title, director, year, the sequence and its place in the film","Para 1 — context: what leads up to the sequence (brief!)","Para 2 — camera: shot types, angles, movement at specific moments","Para 3 — editing: pace of cuts, cross-cutting, rhythm","Para 4 — sound: diegetic/non-diegetic, music, silence","Para 5 — mise-en-scène: lighting, costume, props, setting","Evaluation: how the sequence develops character/theme and why it matters to the whole","Conclusion"]},{"genre":"generic","text":"Any language topic","q":"Choose aspects of language used to promote a film or television programme or product. Identify some examples of the language used and evaluate their effectiveness in achieving the purpose of the promotion.","plan":["Intro: the campaign/adverts you studied, target audience, purpose","Para 1 — slogans and wordplay: specific examples analysed","Para 2 — persuasive devices: imperatives, direct address, rhetorical questions, superlatives","Para 3 — emotive language and connotations of key words","Para 4 — register/tone suited to audience (informal, aspirational)","Evaluation: how effective each example is for its audience/purpose","Conclusion"]},{"genre":"drama","text":"A Streetcar Named Desire — Tennessee Williams","q":"Choose a play in which a character faces a significant challenge or difficulty. Briefly explain the nature of the challenge and discuss how this contributes to your appreciation of the play as a whole.","plan":["Intro: Blanche DuBois arrives at her sister Stella's cramped New Orleans apartment in Elysian Fields, having lost the family home, Belle Reve — her challenge is to survive in a harsh, modern world that has no place for her fragile illusions","Scene 1: stage directions and Blanche's white clothing/'moth-like' appearance vs the raw energy of the street — she does not belong","Clash with Stanley: he represents brute, modern masculinity; their conflict grows from the first scene","Blanche's illusions: paper lantern over the bulb, lies about her past; Mitch offers hope of escape","Stanley exposes her past; birthday scene (Scene 8) — her hopes collapse","Scene 10/11: Stanley's assault and her removal to an asylum — 'I have always depended on the kindness of strangers'","Evaluation: her failure to overcome the challenge creates tragedy and exposes the cruelty of the society around her"]},{"genre":"drama","text":"Macbeth — William Shakespeare","q":"Choose a play in which a central character's flaw leads to their downfall. Discuss how the dramatist presents this and how it contributes to your appreciation of the play as a whole.","plan":["Intro: Macbeth, a brave and loyal general, is destroyed by ambition","The witches' prophecy (Act 1 Sc 3) awakens his ambition; asides reveal 'black and deep desires'","Lady Macbeth's persuasion and his soliloquy weighing the murder of Duncan","The murder and his guilt — hallucinations (dagger), 'sleep no more'","Further murders (Banquo, Macduff's family) show his moral collapse; Banquo's ghost at the banquet","Final acts: isolation, 'Tomorrow, and tomorrow…' soliloquy — despair; killed by Macduff","Evaluation: tragedy of a good man corrupted; order restored with Malcolm — theme of ambition and its consequences"]},{"genre":"drama","text":"The Crucible — Arthur Miller","q":"Choose a play in which a character makes a decision that has important consequences. Discuss how this decision contributes to your appreciation of the play as a whole.","plan":["Intro: Salem, Massachusetts, 1692; John Proctor's decision to tear up his false confession rather than lose his name","Context: hysteria of the witch trials; Miller's parallel with McCarthyism in 1950s America","Proctor's guilt over his affair with Abigail — he sees himself as a sinner","Court scenes: Danforth's rigid authority; Proctor confesses adultery to expose Abigail; Elizabeth's lie to protect him","Act 4: pressure to confess to save his life; signs, then tears the paper — 'Because it is my name!'","Evaluation: integrity and reputation against a corrupt authority; he regains his goodness through sacrifice","Conclusion: the decision gives the tragedy its moral power"]},{"genre":"prose","text":"The Great Gatsby — F. Scott Fitzgerald","q":"Choose a novel in which a character's dream or ambition is important. Discuss how the writer presents this and how it contributes to your appreciation of the novel as a whole.","plan":["Intro: narrated by Nick Carraway; Jay Gatsby's dream of winning back Daisy Buchanan represents the American Dream","Symbol of the green light at the end of Daisy's dock — longing and the unreachable","Gatsby's lavish parties and self-invented past — wealth as a means to the dream","Reunion with Daisy — the dream cannot match reality","Confrontation with Tom at the Plaza Hotel — old money vs new","Myrtle's death and Gatsby's murder by Wilson; few attend his funeral","Evaluation: the dream is corrupted by materialism; ending — 'boats against the current' — the past cannot be repeated"]},{"genre":"prose","text":"Nineteen Eighty-Four — George Orwell","q":"Choose a novel in which the writer explores a theme of political or social importance. Discuss how the writer's presentation of this theme enhances your appreciation of the novel as a whole.","plan":["Intro: Winston Smith in Oceania, ruled by the Party and Big Brother — the dangers of totalitarian control","Setting: telescreens, Thought Police, the Ministry of Truth rewriting history","Language as control: Newspeak; 'doublethink'","Winston's rebellion: the diary, his relationship with Julia","Betrayal by O'Brien; torture in the Ministry of Love; Room 101","Ending: Winston 'loved Big Brother' — total defeat of the individual","Evaluation: a warning about surveillance, propaganda and the destruction of truth"]},{"genre":"prose","text":"Any Scottish short story you studied for critical essay (not your Section 1 text)","q":"Choose a short story with a surprising or significant ending. Discuss how the ending contributes to your appreciation of the story as a whole.","plan":["Remember: you cannot use the same text in both sections, and Section 2 must be a different GENRE from Section 1","Intro: title, writer, the ending in one sentence and why it matters","Para 1 — how the opening sets up expectations","Para 2 — foreshadowing/clues building towards the ending","Para 3 — the ending itself: analyse language, structure, narrative voice","Para 4 — how the ending changes our view of character/theme","Conclusion: evaluate the ending's impact"]},{"genre":"poetry","text":"Dulce et Decorum Est — Wilfred Owen","q":"Choose a poem which deals with an issue of importance to humanity. Discuss how the poet's presentation of the issue enhances your appreciation of the poem as a whole.","plan":["Intro: Owen, a WW1 soldier-poet, exposes the horror of war and attacks the lie that dying for your country is glorious","Stanza 1: exhausted soldiers 'like old beggars' — simile destroys heroic image","Stanza 2: sudden gas attack — 'Gas! GAS! Quick, boys!' — urgency; the drowning image","The dream stanza: the dying man haunts the speaker — lasting trauma","Final stanza: direct address to 'My friend' — graphic imagery; 'the old Lie'","Structure: broken sonnet form, shifts in pace","Evaluation: the bitter, angry tone persuades readers to reject war propaganda"]},{"genre":"poetry","text":"Mid-Term Break — Seamus Heaney","q":"Choose a poem which explores sadness or grief. Discuss how the poet's presentation of this emotion enhances your appreciation of the poem as a whole.","plan":["Intro: Heaney recalls coming home from boarding school after his young brother's death","Opening: 'counting bells knelling' — ominous sound imagery","Contrast of adults' reactions (father crying, mother's 'angry tearless sighs') with the baby cooing","The speaker's embarrassment and numbness as an outsider","The room: snowdrops and candles — calm, gentle imagery; the bruise","Final one-line stanza: 'A four foot box, a foot for every year.' — devastating simplicity","Evaluation: understated tone makes the grief more powerful"]},{"genre":"film","text":"Psycho — Alfred Hitchcock (1960)","q":"Choose a film which contains a particularly disturbing sequence. Explain how the film makers present the sequence and discuss how it contributes to your appreciation of the film as a whole.","plan":["Intro: Marion Crane, on the run with stolen money, stops at the Bates Motel run by Norman Bates","Build-up: parlour scene — stuffed birds, low angles on Norman; hints of his disturbed relationship with 'Mother'","The shower sequence: rapid editing of many short shots; close-ups; the knife never shown entering the body","Sound: Bernard Herrmann's shrieking strings (non-diegetic)","Aftermath: the water swirling down the plughole dissolves into an extreme close-up of Marion's lifeless eye","Evaluation: killing the apparent protagonist early shocks the audience and shifts focus to Norman; themes of identity, guilt and the 'mother'","Conclusion"]},{"genre":"film","text":"The Truman Show — Peter Weir (1998)","q":"Choose a film in which a central character faces a significant challenge. Explain how the film makers present this challenge and discuss how this contributes to your appreciation of the film as a whole.","plan":["Intro: Truman Burbank has unknowingly lived his whole life as the star of a TV show in the artificial town of Seahaven, controlled by the creator Christof","Early clues: a studio light falls from the 'sky'; repeated framing through hidden cameras (vignetted shots)","His growing suspicion and attempts to leave — obstacles staged by the show","Facing his fear of water to sail away; the storm created by Christof","The boat hits the painted sky wall — the 'edge' of his world; stairs to the exit door","Final choice: he bows and walks out — freedom over comfort","Evaluation: themes of reality, media manipulation and free will"]},{"genre":"language","text":"The language of a group (e.g. a sport, hobby or online gaming community)","q":"Choose the language typically used by a particular vocational or leisure group. Identify specific language features, and discuss their contribution to efficient communication within the group.","plan":["Intro: the group, its purpose, how you gathered examples","Jargon/specialist vocabulary — specific examples and what they mean","Abbreviations and acronyms — speed of communication","Slang/in-group terms — identity and belonging","Register and tone in different situations","Evaluation: efficient for insiders, but may exclude outsiders","Conclusion"]},{"genre":"language","text":"Scots language and identity","q":"Choose aspects of language associated with a particular region or community. Discuss how these features contribute to the identity of the community.","plan":["Intro: the variety of Scots you studied (e.g. Glaswegian, Doric, Shetland)","Vocabulary — specific examples with meanings","Grammar features (e.g. 'I seen', 'youse') and pronunciation","Attitudes to Scots — stigma vs pride; recent recognition","Scots in literature, media and online","Evaluation: how language expresses identity and belonging","Conclusion"]},{"genre":"scottish","text":"Any set play — final question template","q":"By referring to the extract and to elsewhere in the play, discuss how [writer] uses [feature: character / conflict / setting] to explore central concerns. (8 marks)","plan":["2 marks — commonality: name the feature and the central concern(s) it explores (1 + 1)","2 marks — the extract: one detailed comment with a quotation/reference linked to the question","4 marks — elsewhere: two detailed comments (2 + 2) or four basic ones from OTHER parts of the play","Bullet points are allowed","Prepare 6–8 key moments with short quotations per theme"]},{"genre":"scottish","text":"Any set poet — final question template","q":"By referring to this poem and to at least one other poem by [poet], discuss how the poet uses [technique: imagery / contrast / symbolism] to explore central concerns. (8 marks)","plan":["2 marks — commonality: e.g. 'X uses imagery of nature and family (1) to explore memory, heritage and loss (1)'","2 marks — this poem: one insightful comment + quotation","4 marks — at least one other poem: two detailed comments (2 + 2), each with a quotation and a link to a central concern","Using two other poems spreads risk if one comment is weak","Learn 2–3 short quotations per poem"]},{"genre":"scottish","text":"Any set prose text — final question template","q":"By referring to this extract and to elsewhere in the novel / at least one other story, discuss how [writer] explores [theme]. (8 marks)","plan":["2 marks — commonality across the text/stories","2 marks — the extract","4 marks — elsewhere: two developed references to other key incidents/stories","For short stories, refer to at least one OTHER story","Avoid retelling — every reference needs a comment on the theme"]}];
