const qType=q=>q.o?'mc':q.p?'written':'num';
const WORKSHEETS=[];
Object.entries(TOPICS).forEach(([k,t])=>{
  const quiz=[],exam=[];
  t.questions.forEach((q,i)=>(qType(q)==='written'?exam:quiz).push(i));
  if(quiz.length)WORKSHEETS.push({title:t.name+' — quick quiz',topic:k,kind:'quiz',diff:'Mixed',qs:quiz});
  if(exam.length)WORKSHEETS.push({title:t.name+' — exam-style',topic:k,kind:'exam',diff:'Exam',qs:exam});
});
const MOCK_PAPERS={"1":{"title":"RUAE Mock Paper 1 — The Lost Art of Boredom","short":"RUAE Mock 1","kind":"ruae","duration":5400,"sections":[{"s":1,"label":"Passage 1 questions","max":25},{"s":2,"label":"Question on both passages","max":5}],"case":{"name":"The Lost Art of Boredom","note":"Both passages were written for this site — they are not real articles. Read Passage 1 and answer questions 1–8. Then read Passage 2 and answer question 9.","passages":[{"title":"Passage 1","intro":"In this passage, a writer reflects on what we lose when we never allow ourselves to be bored.","paras":["When I was nine, the longest afternoon in the world took place every August in my grandmother's front room in Arbroath. The clock ticked like a dripping tap. The rain slid down the window in no particular hurry. There was nothing to watch, nothing to play and, as far as I could tell, nothing to live for. I was, in a word, bored — gloriously, gigantically, unbearably bored.","I mention this because my nine-year-old nephew has never been bored in his life. Not once. He has never stared at a ceiling or counted the flowers on the wallpaper. The moment a silence threatens, a screen arrives to fill it, the way a waiter whisks away an empty plate before you have even put down your fork. In the queue at the supermarket, in the back of the car, in the ninety seconds while the kettle boils — the phone is there, bright and obliging and endlessly patient.","We tend to treat this as a triumph. Boredom, after all, has a terrible reputation. It is the enemy of productivity, the companion of the idle, the nagging sibling of misery. Parents dread it; employers fear it; advertisers have built entire empires on the promise that we need never endure it again. Who, in their right mind, would campaign for more of it?","I would — and I am not alone. Psychologists who study boredom increasingly describe it not as a void but as a signal: an itch that tells us our surroundings are not giving us what we need. Like hunger, it is uncomfortable precisely because it is meant to make us move. The bored child eventually builds a den out of the sofa cushions, writes a play for the cat, or wanders outside to see what the burn is doing. Boredom, in other words, is not the absence of imagination. It is the starting pistol.","The trouble is that the starting pistol never gets fired. Each time the itch begins, we scratch it — instantly, efficiently, and with a device designed by some of the cleverest engineers on the planet to be scratched again and again. We have outsourced our restlessness. The phone does not cure boredom; it merely anaesthetises it, and the operation is so painless that we have forgotten we were ever ill.","Some will say this is the grumbling of every generation. Socrates, we are reminded, worried that writing would destroy memory; the Victorians fretted that novels would corrupt young minds. Every new technology arrives with its chorus of doom-mongers, and every time the world fails to end. That is true. But it is also true that no previous technology followed us into the bathroom, buzzed beside our pillow at three in the morning, or was deliberately built to keep us from putting it down.","Nor is this simply a matter for children. Ask an adult when they last sat on a bus and simply looked out of the window. Ask them when they last allowed a thought to wander from its starting point to somewhere unexpected — the kind of meandering that once produced daydreams, plans, poems and the occasional good idea in the shower. Many of us, if we are honest, cannot remember. Our minds have become like over-tidied rooms: everything in its place, and nowhere left to sit.","I am not suggesting we hurl our phones into the sea. I am suggesting something more modest and, I suspect, more difficult: that every so often we let the afternoon stretch out in front of us, grey and empty and ticking, and see what grows there. My grandmother's front room taught me more than I knew at the time. It taught me that nothing is quite as dull as it first appears — provided you give it long enough."]},{"title":"Passage 2","intro":"In this passage, a teacher considers the value of boredom in the classroom and beyond.","paras":["Every September, a new class arrives in my room convinced that boredom is a kind of injustice. If a lesson is not instantly entertaining, something has gone wrong — with the lesson, the teacher, or possibly the universe. I understand. They have grown up with entertainment on tap, and nobody has ever asked them to wait.","Yet the most productive moment in my classroom is often the most awkward one: the silence after I ask a hard question. For a few seconds nothing happens. Pupils shift in their seats; someone sighs theatrically. Then, slowly, hands go up — not from the quickest pupils, but from the ones who have used the silence to think. Those few uncomfortable seconds do more for their minds than any animated slideshow I could put on the board.","There is good reason to believe this reaches far beyond school. Creative people have long described their best ideas arriving on long walks, train journeys and dull afternoons. Their minds, left without a task, began to make connections on their own. Remove those empty stretches of time and you may remove the space in which original thought takes root.","I do not blame the technology alone. Phones are astonishing tools, and many of my pupils use them brilliantly. But a tool that is always in your hand is no longer a tool; it is a habit. And habits, unlike tools, decide when they will be used.","So, this year, I am trying an experiment. For ten minutes at the start of each lesson, phones go in a box and pupils simply write — about anything, or nothing. The first week was agony. By the third, some of them were asking for longer. Boredom, it turns out, is a muscle. It hurts when you first use it. Then it begins to make you strong."]}]},"questions":[{"s":1,"n":"1","topic":"Word choice / sentence structure","q":"Read paragraph 1. Analyse how the writer's use of language conveys how boring the afternoons in his grandmother's front room were.","m":2,"p":["'The longest afternoon in the world' — hyperbole emphasises how time seemed to drag endlessly","'ticked like a dripping tap' — simile suggests slow, monotonous, irritating repetition","'slid… in no particular hurry' — personification of the rain suggests everything moved slowly/nothing happened","repetition of 'nothing' (to watch, to play, to live for) emphasises the total emptiness; humorous exaggeration 'nothing to live for'","list/climax 'gloriously, gigantically, unbearably bored' — alliteration and build-up stress the extremity of his boredom"]},{"s":1,"n":"2","topic":"Imagery / word choice","q":"Read paragraph 2. By referring to at least two examples, analyse how the writer's use of language suggests that screens fill every moment of his nephew's life.","m":4,"p":["'never been bored… Not once.' — minor sentence/blunt repetition emphasises how absolute this is","'The moment a silence threatens' — personifies silence as a danger, suggesting it is never allowed to happen","'a screen arrives to fill it' — suggests automatic, instant replacement of any empty moment","'like a waiter whisks away an empty plate before you have even put down your fork' — simile: just as an over-attentive waiter removes a plate instantly, the screen removes boredom before it can even be felt","list of everyday situations (queue, car, 'ninety seconds while the kettle boils') — shows the phone appears in even the briefest/most ordinary gaps","'bright and obliging and endlessly patient' — polysyndeton/positive word choice presents the phone as a seductive, ever-available servant"]},{"s":1,"n":"3","topic":"Understanding (own words)","q":"Read paragraph 3. Explain why, according to the writer, boredom 'has a terrible reputation'. Use your own words in your answer.","m":3,"p":["it stops people getting things done/being efficient ('enemy of productivity')","it is associated with lazy people ('companion of the idle')","it is linked to unhappiness ('nagging sibling of misery')","parents are afraid of it/worry about bored children","businesses fear it (bored workers)","advertisers have made huge profits by promising we never need feel it"]},{"s":1,"n":"4","topic":"Imagery","q":"Read paragraph 4. Analyse how the writer uses imagery to convey a positive view of boredom.","m":2,"p":["'a signal' — like a warning light/message, boredom tells us something useful about our needs","'an itch' — something that demands action, prompting us to change our situation","'Like hunger' — just as hunger is uncomfortable but makes us find food, boredom drives us to act","'the starting pistol' — the signal that begins a race, so boredom is the trigger that sets imagination/creativity in motion"]},{"s":1,"n":"5","topic":"Word choice / imagery","q":"Read paragraph 5. By referring to at least two examples, analyse how the writer's use of language conveys his criticism of how we deal with boredom.","m":4,"p":["'the starting pistol never gets fired' — extends the earlier image: our creativity never even gets started","'we scratch it — instantly, efficiently' — the dash and list stress how automatic and thoughtless our response is","'designed by some of the cleverest engineers… to be scratched again and again' — suggests deliberate manipulation by tech companies","'We have outsourced our restlessness' — business jargon suggests we have handed over part of ourselves to others","'does not cure boredom; it merely anaesthetises it' — medical imagery/antithesis: it numbs the symptom without solving the problem","'so painless that we have forgotten we were ever ill' — suggests we are unaware of the damage being done"]},{"s":1,"n":"6","topic":"Structure / understanding","q":"Read paragraph 6. Explain how the writer acknowledges and then responds to a counter-argument. You should refer to his ideas and his use of language.","m":3,"p":["he admits critics say every generation complains about new technology (e.g. Socrates on writing, Victorians on novels) — and that the world has never ended ('That is true')","'chorus of doom-mongers' — mocking image shows he recognises the critics' point","'But it is also true…' — signals the turn to his rebuttal","phones are different: they follow us everywhere — 'into the bathroom… beside our pillow' — showing unprecedented intrusion","they are 'deliberately built' to stop us putting them down — unlike earlier technologies"]},{"s":1,"n":"7","topic":"Imagery / word choice","q":"Read paragraph 7. Analyse how the writer's use of language suggests that adults have also lost the ability to let their minds wander.","m":3,"p":["'Ask an adult…' — repetition of direct challenge/rhetorical questioning invites the reader to test themselves","'simply looked out of the window' — 'simply' suggests something once ordinary has become rare","'meandering' — like a slow, winding river, suggests the free, unplanned movement of thought we have lost","list 'daydreams, plans, poems and the occasional good idea in the shower' — shows the range of valuable things that came from wandering minds; humorous anticlimax","'Many of us, if we are honest, cannot remember' — parenthesis makes it a confession shared with the reader","'like over-tidied rooms: everything in its place, and nowhere left to sit' — simile: an over-ordered room is unwelcoming/uncomfortable, so our minds are too organised to allow rest or creativity"]},{"s":1,"n":"8","topic":"Evaluation (conclusion)","q":"Read paragraph 8. Evaluate the effectiveness of this final paragraph as a conclusion to the passage as a whole.","m":4,"p":["'I am not suggesting we hurl our phones into the sea' — anticipates the objection that he is extreme; makes his stance reasonable","'more modest and, I suspect, more difficult' — honest/balanced tone strengthens his argument","returns to his grandmother's front room from paragraph 1 — cyclical structure gives a sense of completion","'grey and empty and ticking' — echoes the clock and rain of the opening, now reframed positively","'see what grows there' — growth image links to boredom as the 'starting pistol'/source of imagination (para 4)","final sentence — 'nothing is quite as dull as it first appears' — a memorable, reflective summing-up of his whole argument; the dash adds a final emphatic condition"]},{"s":2,"n":"9","topic":"Both passages (comparison)","q":"Look at both passages. Both writers express their views about boredom. Identify three key areas on which they agree. You should support the points by referring to important ideas in both passages. You may answer in continuous prose or a series of developed bullet points.","m":5,"p":["AREA — Boredom is unpopular/seen as something to avoid. P1: 'terrible reputation', parents dread it, advertisers promise we never need endure it. P2: pupils see boredom as 'a kind of injustice'; lessons must be instantly entertaining","AREA — Boredom/empty time is valuable because it leads to creativity and thought. P1: 'the starting pistol'; dens, plays, daydreams, poems, ideas in the shower. P2: silence after a hard question is the most productive moment; best ideas arrive on walks and dull afternoons","AREA — Technology/phones have removed boredom from our lives. P1: a screen fills every silence; phone in the queue, car, while the kettle boils. P2: entertainment on tap; a phone always in your hand becomes a habit","AREA — Phones are not wholly bad; the answer is moderation. P1: 'not suggesting we hurl our phones into the sea'. P2: 'astonishing tools'; 'I do not blame the technology alone'","AREA — Learning to tolerate boredom is difficult at first but rewarding. P1: 'more modest and… more difficult'; 'provided you give it long enough'. P2: the first week was 'agony' but pupils later asked for longer; 'a muscle… begins to make you strong'","MARKING: 5 = three key areas with detailed/insightful evidence from both passages; 4 = three areas with appropriate evidence; 3 = three areas; 2 = two areas; 1 = one area"]}]},"2":{"title":"RUAE Mock Paper 2 — Loved to Death? Tourism in the Highlands","short":"RUAE Mock 2","kind":"ruae","duration":5400,"sections":[{"s":1,"label":"Passage 1 questions","max":25},{"s":2,"label":"Question on both passages","max":5}],"case":{"name":"Loved to Death? Tourism in the Highlands","note":"Both passages were written for this site — they are not real articles, and the places described are composites. Read Passage 1 and answer questions 1–8. Then read Passage 2 and answer question 9.","passages":[{"title":"Passage 1","intro":"In this passage, a writer who grew up in a Highland village considers the effects of mass tourism.","paras":["The road past my mother's house was once so quiet that a passing car was an event. We would look up from the garden to see who it was, and nine times out of ten we would wave, because nine times out of ten we knew them. Now, on a summer afternoon, the road is a slow-moving river of metal: campervans, convertibles and coaches, nose to tail, inching towards a viewpoint made famous by a single photograph.","I do not blame the visitors for coming. The glen is beautiful — absurdly, almost embarrassingly beautiful — and it would be a strange kind of meanness to want it all to ourselves. Tourists bring money to places that badly need it. They keep the hotel open, the café busy and the petrol station from closing, and they have given dozens of young people a reason to stay rather than drift south in search of work.","But love, as anyone who has been in a relationship will tell you, can be suffocating. The single-track road was built for tractors and the post van, not for a convoy of motorhomes the size of small houses. Passing places, intended as courteous pauses, have become car parks. Verges are churned to mud. The layby at the head of the loch, once a spot for a quiet flask of tea, now resembles the aftermath of a music festival.","And then there is the litter — or rather, the litter and worse. Every local has a story. A family picnic abandoned on the shore, complete with disposable barbecue scorching the grass. Toilet paper fluttering from the heather like grim bunting. A fire ring of blackened stones on a beach where curlews nest. Most visitors, of course, are careful and considerate. It takes only a few who are not.","Those who promote the area have, in a sense, been too successful. For years the message was simple: come. Come and see the mountains, come and drive the open road, come and find the 'real' Scotland. Nobody thought to add a second sentence — come, but tread lightly — and nobody paid for the toilets, bins and car parks that such an invitation demanded.","The result is a peculiar kind of resentment, and it troubles me, because Highlanders have a long and proud tradition of welcome. My grandmother would have fed a stranger before she asked his name. Yet in the village shop this summer I heard a neighbour mutter that she no longer recognised her own home. She was not being dramatic. She was being honest.","Some argue that the answer is simply to charge: a fee for parking, a tourist tax, a toll on the most popular routes. Others say this would punish the many for the sins of the few, and price out the families who most deserve a holiday. Both camps have a point. What is clear is that doing nothing is no longer an option. A place cannot be loved to death and remain the place people came to love.","On a wet Tuesday in October, the road past my mother's house is quiet again. The coaches have gone; the verges are slowly healing. For a few months, the glen breathes out. The question is whether, next summer, we will have learned how to share it — or whether we will simply hold our breath and hope."]},{"title":"Passage 2","intro":"In this passage, a tourism worker gives a different perspective.","paras":["I run a small guiding business, and I spend my summers watching people fall in love with the Highlands. I see their faces at the top of a ridge or the moment an otter surfaces in the loch. Tourism is not an invasion. For many of these places, it is a lifeline.","That does not mean everything is fine. On the busiest roads the pressure is real: queues at viewpoints, overflowing bins, campervans parked where they should not be. Local people are right to be angry when their passing places are blocked and their beaches are left strewn with rubbish.","But the problem is not the number of visitors so much as the lack of preparation for them. For too long, communities were encouraged to attract tourists without being given the means to cope with them. Build proper facilities, and much of the bad behaviour disappears; most people would far rather use a clean toilet than a hillside.","I would welcome a small visitor levy, provided every penny is spent locally — on rangers, bins, paths and parking. Visitors I talk to are, almost without exception, happy to contribute to the upkeep of places they love. What they object to is paying into a black hole.","The Highlands have always been shaped by people coming and going. The challenge now is to make sure that those who arrive leave the place as they found it — and that those who live here feel the benefit, not just the burden."]}]},"questions":[{"s":1,"n":"1","topic":"Understanding (own words)","q":"Read paragraph 1. Explain how the road past the writer's mother's house has changed. Use your own words in your answer.","m":2,"p":["it used to be very quiet/cars were rare ('a passing car was an event')","in the past the family knew most of the people driving past","now it is extremely busy/congested with many types of vehicle","the traffic moves very slowly/in long queues towards a famous viewpoint"]},{"s":1,"n":"2","topic":"Word choice / imagery","q":"Read paragraph 1. Analyse how the writer's use of language conveys the scale of the summer traffic.","m":2,"p":["'a slow-moving river of metal' — metaphor: like a river, the traffic is continuous and never-ending; 'metal' makes it cold and unnatural","list 'campervans, convertibles and coaches' — alliteration and variety stress the range and volume of vehicles","'nose to tail' — suggests vehicles packed tightly together, like animals in a line","'inching' — suggests painfully slow progress"]},{"s":1,"n":"3","topic":"Understanding (own words)","q":"Read paragraph 2. Explain the benefits that tourism brings to the area. Use your own words in your answer.","m":3,"p":["it brings in money/income to an area that is short of it","it keeps local businesses going (hotel, café, petrol station) / prevents them closing","it creates jobs that give young people a reason to remain in the area rather than move away"]},{"s":1,"n":"4","topic":"Sentence structure / tone","q":"Read paragraph 2. Analyse how the writer's language creates a fair and balanced tone.","m":2,"p":["'I do not blame the visitors for coming.' — short, direct opening statement makes clear he is not hostile","parenthesis/repetition 'absurdly, almost embarrassingly beautiful' — humorous admission that people are right to want to visit","'a strange kind of meanness' — he criticises the idea of keeping the area to locals","list of benefits (hotel, café, petrol station, young people) — shows he recognises tourism's real value"]},{"s":1,"n":"5","topic":"Imagery / word choice","q":"Read paragraphs 3 and 4. By referring to at least two examples, analyse how the writer's use of language conveys the damage caused by tourism.","m":4,"p":["'love… can be suffocating' — metaphor: too much affection smothers; the area is overwhelmed by visitors' enthusiasm","'motorhomes the size of small houses' — exaggeration stresses how unsuitable the vehicles are for small roads","'courteous pauses' vs 'have become car parks' — contrast shows how their purpose has been abused","'churned to mud' — suggests violent, destructive damage to the verges","'resembles the aftermath of a music festival' — simile suggests mess, chaos and rubbish","'the litter and worse' — the dash/correction hints at something unpleasant, building disgust","'like grim bunting' — simile: bunting is festive, so the ironic image makes the toilet paper grotesque","'disposable barbecue scorching the grass' / 'fire ring… where curlews nest' — word choice shows harm to wildlife and the landscape"]},{"s":1,"n":"6","topic":"Understanding / structure","q":"Read paragraph 5. Explain why, according to the writer, those who promote the area have 'been too successful'.","m":3,"p":["they persuaded large numbers of people to visit (the message was simply 'come')","they did not also tell visitors to behave responsibly/respect the area ('tread lightly')","they did not pay for/provide the facilities needed for so many visitors (toilets, bins, car parks)"]},{"s":1,"n":"7","topic":"Word choice / sentence structure","q":"Read paragraph 6. Analyse how the writer's use of language conveys his unease about the change in local attitudes.","m":4,"p":["'peculiar kind of resentment' — 'peculiar' suggests the feeling is unusual/out of character for the community","'it troubles me' — direct personal admission of his discomfort","'long and proud tradition of welcome' — positive word choice stresses what is being lost","'My grandmother would have fed a stranger before she asked his name' — anecdote shows the depth of past hospitality, contrasting with present resentment","'mutter' — suggests quiet, bitter complaining","'no longer recognised her own home' — suggests people feel like strangers in their own place","short sentences 'She was not being dramatic. She was being honest.' — balanced, emphatic structure insists the feeling is genuine"]},{"s":1,"n":"8","topic":"Evaluation (conclusion)","q":"Read paragraphs 7 and 8. Evaluate how effective these paragraphs are as a conclusion to the passage.","m":5,"p":["para 7 presents both sides of the debate on charging ('Both camps have a point') — continues the balanced tone of the passage","'doing nothing is no longer an option' — firm, clear stance sums up his argument","'A place cannot be loved to death…' — memorable, paradoxical final line of para 7 echoes the 'love… suffocating' image in para 3","para 8 returns to 'the road past my mother's house' from the opening — cyclical structure","'quiet again', 'verges are slowly healing' — contrasts with the opening traffic and 'churned' verges; personification suggests recovery","'the glen breathes out' / 'hold our breath' — breathing image links back to 'suffocating', ending on an uncertain, thought-provoking question"]},{"s":2,"n":"9","topic":"Both passages (comparison)","q":"Look at both passages. The writers agree about some aspects of tourism in the Highlands. Identify three key areas on which they agree. You should support the points by referring to important ideas in both passages. You may answer in continuous prose or a series of developed bullet points.","m":5,"p":["AREA — Tourism brings real benefits/is vital to the area. P1: money, keeps hotel/café/petrol station open, keeps young people in the area. P2: 'not an invasion… a lifeline'","AREA — There are serious problems caused by some visitors. P1: blocked passing places, churned verges, litter, toilet paper, fires. P2: queues at viewpoints, overflowing bins, campervans where they should not be, beaches strewn with rubbish","AREA — Local anger/resentment is understandable. P1: 'a peculiar kind of resentment'; neighbour 'no longer recognised her own home' — 'She was being honest'. P2: 'Local people are right to be angry'","AREA — The root cause is a lack of facilities/planning, not the visitors themselves. P1: nobody paid for toilets, bins and car parks; 'most visitors… are careful'. P2: 'lack of preparation'; communities not given the means to cope","AREA — Something must be done, possibly including charges. P1: 'doing nothing is no longer an option'; fees/tourist tax debated. P2: welcomes a small visitor levy spent locally","MARKING (this paper's final question is worth 5 marks): 5 = three areas, detailed/insightful evidence; 4 = three areas, appropriate evidence; 3 = three areas; 2 = two; 1 = one"]}]},"3":{"title":"Knowledge Test — RUAE, Essay Skills & Terminology","short":"Skills test","kind":"quiz","duration":1500,"count":25,"areas":["ruae","ce","term"]},"4":{"title":"Knowledge Test — Scottish Set Texts","short":"Set texts test","kind":"quiz","duration":1500,"count":25,"areas":["skills","drama","prose","poetry"]},"5":{"title":"Knowledge Test — Whole Course","short":"Whole-course test","kind":"quiz","duration":1800,"count":30,"areas":["ruae","ce","skills","drama","prose","poetry","pf","term"]}};
Object.values(MOCK_PAPERS).forEach(p=>{if(p.questions)p.totalMarks=p.questions.reduce((a,q)=>a+q.m,0);});
